import { GoogleGenAI } from "@google/genai";
import { ProductData } from "../types";

/**
 * Generates an optimized image generation prompt based on product data.
 */
export const generateOptimizedPrompt = async (data: ProductData): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const parts: any[] = [];

    if (data.imageBase64 && data.mimeType) {
      const base64Data = data.imageBase64.split(',')[1];
      parts.push({
        inlineData: {
          mimeType: data.mimeType,
          data: base64Data
        }
      });
    }

    const promptInput = `
    Role: You are an expert AI Prompt Engineer for pharmaceutical advertising.
    Task: Write a single, highly detailed English text-to-image prompt for Gemini Image 3.

    INPUT DATA:
    - Product Name: ${data.name}
    - Spec: ${data.dosage}
    - Usage: ${data.usage}
    - Price: ${data.listPrice}
    - Manufacturer: ${data.manufacturer}
    - Layout: ${data.aspectRatio === 'vertical' ? 'Vertical 9:16' : 'Horizontal 16:9'}

    PROMPT STRUCTURE:
    1. Visual Description: High-end medical studio setting, cinematic lighting.
    2. Text Overlays: COMMAND the model to render "${data.name}" in massive 3D typography. 
    3. Hierarchy: Name is largest, List Price is bold and visible, Manufacturer at bottom.
    ${data.isETC ? '- Label: "Thuốc kê toa" in red.' : ''}

    OUTPUT: ONLY the prompt string.
    `;

    parts.push({ text: promptInput });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview', 
      contents: [{ role: 'user', parts: parts }]
    });

    return response.text || "Failed to generate prompt.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error; 
  }
};

/**
 * Processes a product image using Gemini 2.5 Flash Image for specialized tasks.
 */
export const processProductImageAI = async (
  base64Image: string, 
  mimeType: string, 
  task: 'remove-bg' | 'make-3d'
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Clean base64
  const data = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;

  const prompts = {
    'remove-bg': "Please remove the background of this pharmaceutical product image. Return only the product on a pure, clean white background. Preserve all text and details on the packaging perfectly.",
    'make-3d': "Transform this product packaging into a high-quality, professional 3D isometric medicine box presentation. It should look like a real 3D box standing on a clean surface with soft shadows. Ensure the branding and text are perfectly readable."
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data, mimeType } },
          { text: prompts[task] }
        ]
      }
    });

    // Find the image part in response
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }

    throw new Error("AI did not return an edited image.");
  } catch (error) {
    console.error("Image Processing Error:", error);
    throw error;
  }
};

