import React, { useState } from 'react';
import { ProductForm } from './components/ProductForm';
import { ResultDisplay } from './components/ResultDisplay';
import { ExternalToolModal } from './components/ExternalToolModal';
import { ExcelImportModal } from './components/ExcelImportModal';
import { ProductData, GeneratedResult, AppState, ExcelMapping } from './types';
import { generateOptimizedPrompt, processProductImageAI } from './services/geminiService';
import { PenTool, BrainCircuit, Table, Image as ImageIcon } from 'lucide-react';
import useLocalStorage from './hooks/useLocalStorage';

const createEmptyProduct = (id: number): ProductData => ({
  id,
  name: '',
  dosage: '',
  usage: '',
  isETC: false,
  listPrice: '',
  idecoPrice: '',
  manufacturer: '',
  description: '',
  imageBase64: undefined,
  mimeType: undefined,
  aspectRatio: 'vertical'
});

const App: React.FC = () => {
  const [products, setProducts] = useState<ProductData[]>([
    createEmptyProduct(1),
    createEmptyProduct(2),
    createEmptyProduct(3)
  ]);

  const [activeTab, setActiveTab] = useState<number>(1);
  const [results, setResults] = useState<GeneratedResult[]>([
    { id: 1, prompt: '', status: 'pending' },
    { id: 2, prompt: '', status: 'pending' },
    { id: 3, prompt: '', status: 'pending' }
  ]);

  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [isImageProcessing, setIsImageProcessing] = useState(false);

  const [masterLibrary, setMasterLibrary] = useLocalStorage<any[]>('excelMasterLibrary', []);
  const [columnMapping, setColumnMapping] = useLocalStorage<ExcelMapping>('excelColumnMapping', {
    name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: ''
  });

  const [externalTool, setExternalTool] = useState<{ isOpen: boolean; type: 'mind' | 'image' | null }>({
    isOpen: false,
    type: null
  });

  const [excelModalOpen, setExcelModalOpen] = useState(false);

  const handleFieldChange = (id: number, field: keyof ProductData, value: string | boolean) => {
    setProducts(prev => prev.map(p => p.id === id ? { ...p, [field]: value } : p));
  };

  const handleImageUpload = (id: number, file: File) => {
    if (file.size > 5 * 1024 * 1024) {
      alert("Ảnh quá lớn. Vui lòng chọn ảnh dưới 5MB.");
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => {
      setProducts(prev => prev.map(p => p.id === id ? { 
        ...p, 
        imageBase64: reader.result as string,
        mimeType: file.type
      } : p));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = (id: number) => {
    setProducts(prev => prev.map(p => p.id === id ? { ...p, imageBase64: undefined, mimeType: undefined } : p));
  };

  /**
   * AI Image Processing (Remove BG / Make 3D)
   */
  const handleProcessImage = async (id: number, task: 'remove-bg' | 'make-3d') => {
    const product = products.find(p => p.id === id);
    if (!product?.imageBase64 || !product.mimeType) return;

    setIsImageProcessing(true);
    try {
      const processedBase64 = await processProductImageAI(product.imageBase64, product.mimeType, task);
      setProducts(prev => prev.map(p => p.id === id ? { 
        ...p, 
        imageBase64: processedBase64,
        mimeType: 'image/png' // AI returns high quality PNG
      } : p));
    } catch (error) {
      alert("Lỗi xử lý ảnh: " + (error instanceof Error ? error.message : "Vui lòng thử lại."));
    } finally {
      setIsImageProcessing(false);
    }
  };

  const handleGenerateAll = async () => {
    if (!process.env.API_KEY) {
        alert("Thiếu API Key.");
        return;
    }

    setAppState(AppState.PROCESSING);
    setResults(prev => prev.map(r => {
        const prod = products.find(p => p.id === r.id);
        if (prod && prod.name) return { ...r, status: 'loading', prompt: '' };
        return r;
    }));

    const promises = products.map(async (product) => {
      if (!product.name) return;
      try {
        const prompt = await generateOptimizedPrompt(product);
        setResults(prev => prev.map(r => r.id === product.id ? { ...r, prompt, status: 'success' } : r));
      } catch (error) {
        setResults(prev => prev.map(r => r.id === product.id ? { ...r, prompt: String(error), status: 'error' } : r));
      }
    });

    await Promise.all(promises);
    setAppState(AppState.COMPLETE);
  };

  const handleExcelImport = (importedProducts: ProductData[], rawData: any[], mapping: ExcelMapping) => {
    setMasterLibrary(rawData);
    setColumnMapping(mapping);
    setProducts(prev => {
        const newProducts = [...prev];
        importedProducts.forEach((imp, index) => {
            if (index < 3) {
                newProducts[index] = { ...createEmptyProduct(index + 1), ...imp, id: index + 1 };
            }
        });
        return newProducts;
    });
  };

  const handleApplyProductFromLibrary = (productIndex: number, libraryItem: any) => {
    const formatPrice = (val: any, pack: any) => {
        let p = typeof val === 'number' ? val.toLocaleString('vi-VN') + ' đ' : String(val || '');
        return pack ? `${p} / ${pack}` : p;
    };

    const newProductData: Partial<ProductData> = {
        name: String(libraryItem[columnMapping.name] || ''),
        dosage: String(libraryItem[columnMapping.dosage] || ''),
        usage: String(libraryItem[columnMapping.usage] || ''),
        listPrice: formatPrice(libraryItem[columnMapping.listPrice], libraryItem[columnMapping.packaging]),
        idecoPrice: formatPrice(libraryItem[columnMapping.idecoPrice], libraryItem[columnMapping.packaging]),
        manufacturer: String(libraryItem[columnMapping.manufacturer] || ''),
    };

    setProducts(prev => prev.map(p => p.id === productIndex ? { ...p, ...newProductData } : p));
  };

  return (
    <div className="min-h-screen bg-slate-100 p-4 md:p-8">
      <div className="max-w-7xl mx-auto space-y-6">
        <header className="flex flex-col md:flex-row items-center justify-between pb-4 gap-4">
          <div className="flex items-center gap-3">
            <div className="bg-indigo-600 text-white p-2.5 rounded-xl shadow-lg"><PenTool className="w-6 h-6" /></div>
            <div>
              <h1 className="text-2xl md:text-3xl font-extrabold text-slate-800">Pharma Prompt AI</h1>
              <p className="text-slate-500 text-sm font-medium">Xử lý ảnh & tạo Prompt hàng loạt (3 SP)</p>
            </div>
          </div>

          <div className="flex gap-3">
            <button onClick={() => setExcelModalOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-white text-emerald-700 font-bold rounded-lg shadow border border-emerald-200 hover:bg-emerald-50"><Table className="w-5 h-5" /> Excel</button>
            <button onClick={() => window.open('https://lmarena.ai/', '_blank')} className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-pink-500 to-rose-500 text-white font-bold rounded-lg shadow-md hover:shadow-lg"><ImageIcon className="w-5 h-5" /> Tạo Ảnh</button>
            <button onClick={() => setExternalTool({ isOpen: true, type: 'mind' })} className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white font-bold rounded-lg shadow-md hover:shadow-lg"><BrainCircuit className="w-5 h-5" /> Mind</button>
          </div>
        </header>

        <main className="grid grid-cols-1 lg:grid-cols-12 gap-6">
          <div className="lg:col-span-7">
            <ProductForm 
              products={products} activeTab={activeTab} onTabChange={setActiveTab} onChange={handleFieldChange}
              onImageUpload={handleImageUpload} onRemoveImage={handleRemoveImage} onSubmit={handleGenerateAll}
              onProcessImage={handleProcessImage} isProcessing={appState === AppState.PROCESSING} isImageProcessing={isImageProcessing}
              masterLibrary={masterLibrary} columnMapping={columnMapping} onApplyLibraryProduct={handleApplyProductFromLibrary}
            />
          </div>
          <div className="lg:col-span-5">
            <ResultDisplay results={results} appState={appState} />
          </div>
        </main>
      </div>

      <ExternalToolModal 
        isOpen={externalTool.isOpen} onClose={() => setExternalTool({ isOpen: false, type: null })}
        url={externalTool.type === 'mind' ? 'https://geminigen.ai' : ''} title="GeminiGen AI" icon={<BrainCircuit className="w-5 h-5"/>}
      />

      <ExcelImportModal 
        isOpen={excelModalOpen} onClose={() => setExcelModalOpen(false)}
        onImport={handleExcelImport} onSave={(rawData, mapping) => { setMasterLibrary(rawData); setColumnMapping(mapping); }}
        savedData={masterLibrary} savedMapping={columnMapping}
      />
    </div>
  );
};

export default App;

import React, { useRef, useState, useMemo } from 'react';
import { ProductData, ExcelMapping } from '../types';
import { Pill, DollarSign, Factory, FileText, Tag, Upload, Trash2, HeartPulse, Smartphone, Monitor, Quote, Search, Link as LinkIcon, Download, X, Box, Eraser, Loader2, AlertCircle } from 'lucide-react';
import { Sparkles } from 'lucide-react';

interface ProductFormProps {
  products: ProductData[];
  activeTab: number;
  onTabChange: (id: number) => void;
  onChange: (id: number, field: keyof ProductData, value: string | boolean) => void;
  onImageUpload: (id: number, file: File) => void;
  onRemoveImage: (id: number) => void;
  onSubmit: () => void;
  onProcessImage: (id: number, task: 'remove-bg' | 'make-3d') => Promise<void>;
  isProcessing: boolean;
  isImageProcessing: boolean;
  masterLibrary?: any[];
  columnMapping?: ExcelMapping;
  onApplyLibraryProduct?: (id: number, libraryItem: any) => void;
}

const PROMPT_TEMPLATES = [
  { id: 'female_patient', label: '👩 Nữ bệnh nhân', text: 'Tạo poster chuyên nghiệp. Một bệnh nhân nữ trung niên người Việt Nam, tay cầm sản phẩm, tươi cười, tại phòng khám hiện đại.' },
  { id: 'doctor_consult', label: '👨‍⚕️ Bác sĩ tư vấn', text: 'Bác sĩ nam đang tư vấn, cầm hộp sản phẩm đưa về hướng bệnh nhân nam. Nền sáng, chuyên nghiệp.' },
  { id: 'packshot_3d', label: '📦 Packshot 3D', text: 'Chụp packshot sản phẩm 3D chuyên nghiệp, đặt trên bục sang trọng, ánh sáng cinematic.' }
];

export const ProductForm: React.FC<ProductFormProps> = ({ 
  products, activeTab, onTabChange, onChange, onImageUpload, onRemoveImage, onSubmit, onProcessImage,
  isProcessing, isImageProcessing, masterLibrary = [], columnMapping, onApplyLibraryProduct
}) => {
  const activeProduct = products.find(p => p.id === activeTab) || products[0];
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [imageUrlInput, setImageUrlInput] = useState('');
  const [isUrlLoading, setIsUrlLoading] = useState(false);

  const suggestions = useMemo(() => {
    if (!activeProduct.name || !masterLibrary.length || !columnMapping?.name) return [];
    const lowerInput = activeProduct.name.toLowerCase();
    const nameKey = columnMapping.name;
    return masterLibrary
        .filter(item => item[nameKey] && String(item[nameKey]).toLowerCase().includes(lowerInput))
        .slice(0, 5);
  }, [activeProduct.name, masterLibrary, columnMapping]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>, field: keyof ProductData) => {
    onChange(activeTab, field, e.target.value);
    if (field === 'name') setShowSuggestions(true);
  };

  const handleSuggestionClick = (item: any) => {
      onApplyLibraryProduct?.(activeTab, item);
      setShowSuggestions(false);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) onImageUpload(activeTab, e.target.files[0]);
  };

  const handleUrlLoad = async () => {
    if (!imageUrlInput.trim()) return;
    setIsUrlLoading(true);
    try {
      const response = await fetch(imageUrlInput);
      const blob = await response.blob();
      const file = new File([blob], "image_from_url.png", { type: blob.type });
      onImageUpload(activeTab, file);
      setImageUrlInput('');
    } catch (e) {
      alert("Lỗi tải ảnh. Vui lòng thử lại hoặc tải ảnh về máy rồi upload thủ công.");
    } finally {
      setIsUrlLoading(false);
    }
  };

  const downloadProductImage = () => {
    if (!activeProduct.imageBase64) return;
    const link = document.createElement('a');
    link.href = activeProduct.imageBase64;
    const fileName = activeProduct.name ? activeProduct.name.trim().replace(/\s+/g, '_') : `Product_${activeTab}`;
    link.download = `${fileName}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="bg-white rounded-xl shadow-lg flex flex-col h-full border border-slate-200">
      <div className="flex border-b border-slate-200 bg-slate-50 rounded-t-xl overflow-hidden">
        {products.map((p) => (
          <button
            key={p.id}
            onClick={() => onTabChange(p.id)}
            className={`flex-1 py-3 text-sm font-semibold transition-all border-r border-slate-200 last:border-r-0
              ${activeTab === p.id ? 'bg-white text-emerald-700 border-t-2 border-t-emerald-500 shadow-sm' : 'text-slate-500 hover:bg-slate-100'}`}
          >
            Sản phẩm {p.id}
          </button>
        ))}
      </div>

      <div className="p-6 md:p-8 flex-1 overflow-y-auto custom-scrollbar">
        <div className="flex items-center justify-between mb-6 gap-3">
            <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                <Pill className="w-5 h-5 text-emerald-600" /> Thông Tin SP {activeTab}
            </h2>
            <div className="bg-slate-100 p-1 rounded-lg flex border border-slate-200">
                <button onClick={() => onChange(activeTab, 'aspectRatio', 'vertical')} className={`px-3 py-1 text-xs font-bold rounded-md flex items-center gap-1 transition-all ${activeProduct.aspectRatio === 'vertical' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}><Smartphone className="w-3 h-3" /> Dọc</button>
                <button onClick={() => onChange(activeTab, 'aspectRatio', 'horizontal')} className={`px-3 py-1 text-xs font-bold rounded-md flex items-center gap-1 transition-all ${activeProduct.aspectRatio === 'horizontal' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}><Monitor className="w-3 h-3" /> Ngang</button>
            </div>
        </div>

        <div className="space-y-5">
          {/* Image Area */}
          <div className="border-2 border-dashed border-slate-300 rounded-lg p-4 bg-slate-50/50 hover:bg-white hover:border-emerald-400 transition-colors relative group">
            <div className="flex justify-between items-center mb-2">
                <span className="text-sm font-medium text-slate-700">Ảnh Sản Phẩm (Gốc/Xử lý)</span>
                {activeProduct.imageBase64 && (
                    <div className="flex gap-2">
                        <button onClick={downloadProductImage} className="text-xs text-blue-600 font-bold flex items-center gap-1 hover:underline" title="Tải ảnh sản phẩm về máy">
                            <Download className="w-3 h-3" /> Tải về
                        </button>
                        <button onClick={() => onRemoveImage(activeTab)} className="text-xs text-red-500 font-bold flex items-center gap-1 hover:underline">
                            <Trash2 className="w-3 h-3" /> Xóa
                        </button>
                    </div>
                )}
            </div>

            <input type="file" accept="image/*" ref={fileInputRef} onChange={handleFileChange} className="hidden" />

            {!activeProduct.imageBase64 ? (
              <div className="space-y-4">
                  <div onClick={() => fileInputRef.current?.click()} className="cursor-pointer flex flex-col items-center justify-center py-6 text-slate-400">
                    <Upload className="w-8 h-8 mb-2 opacity-50" />
                    <p className="text-sm">Click để tải ảnh lên</p>
                  </div>
                  <div className="flex items-center gap-2 border-t border-slate-200 pt-4">
                     <LinkIcon className="w-4 h-4 text-slate-400" />
                     <input 
                        type="text" placeholder="Dán link ảnh (URL) vào đây..."
                        className="flex-1 text-xs border border-slate-300 rounded px-3 py-2 outline-none"
                        value={imageUrlInput} onChange={(e) => setImageUrlInput(e.target.value)}
                     />
                     <button onClick={handleUrlLoad} disabled={!imageUrlInput.trim() || isUrlLoading} className="text-xs bg-emerald-600 text-white px-4 py-2 rounded font-bold disabled:opacity-50">
                        {isUrlLoading ? '...' : 'Tải'}
                     </button>
                  </div>
              </div>
            ) : (
              <div className="flex flex-col gap-4">
                <div className="flex items-center gap-4">
                    <div className="w-24 h-24 rounded-lg overflow-hidden border border-slate-200 bg-white relative shrink-0">
                        {isImageProcessing && (
                            <div className="absolute inset-0 bg-white/60 flex items-center justify-center z-10">
                                <Loader2 className="w-6 h-6 text-emerald-600 animate-spin" />
                            </div>
                        )}
                        <img src={activeProduct.imageBase64} alt="Product" className="w-full h-full object-contain" />
                    </div>
                    <div className="flex-1 space-y-2">
