                            <button onClick={() => fileInputRef.current?.click()} className="px-3 py-1.5 bg-slate-200 text-slate-600 rounded text-xs font-bold hover:bg-slate-300 transition-colors">Đổi ảnh</button>
                        </div>
                    </div>
                </div>
              </div>
