import { GoogleGenAI } from "@google/genai";
import { ProductData } from "../types";

/**
 * Generates an optimized image generation prompt based on product data.
 */
export const generateOptimizedPrompt = async (data: ProductData): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const parts: any[] = [];

    if (data.imageBase64 && data.mimeType) {
      const base64Data = data.imageBase64.split(',')[1];
      parts.push({
        inlineData: {
          mimeType: data.mimeType,
          data: base64Data
        }
      });
    }

    const promptInput = `
    Role: World-Class Pharmaceutical Advertising Creative Director.
    Task: Write a master-level English text-to-image prompt for a premium marketing poster.

    CONTENT HIERARCHY (MUST FOLLOW EXACTLY):
    1. PRIMARY BRAND IDENTITY (Title 1): "${data.name}". 
       - IF AN IMAGE IS PROVIDED: Analyze the reference image and prioritize extracting the exact brand name and logo style from it.
       - Render this in massive, high-end 3D metallic or glass-textured typography at the top.

    2. THE VISUAL CENTERPIECE (Title 3 - IDECO Price): "${data.idecoPrice}".
       - THIS IS THE MOST IMPORTANT TEXT. It must be 2x larger than the list price.
       - Style: Glowing neon effects, premium golden badge background, or bold 3D liquid metal finish. 
       - It must be extremely attractive, eye-catching, and impossible to miss.

    3. SECONDARY INFORMATION (Title 2 - List Price): "${data.listPrice}".
       - Render this smaller than the IDECO price, positioned nearby. Use a clean, professional font.

    4. SUB-TEXT: "${data.dosage}" and "${data.usage}".
       - Neatly placed as descriptors for the product.

    5. REGULATORY FOOTER (Title 4 - Manufacturer): "Nhà sản xuất: ${data.manufacturer}".
       - Elegant, small font at the very bottom of the poster.

    ${data.isETC ? '6. MANDATORY REGULATORY LABEL: In the ABSOLUTE TOP-LEFT corner, place a high-contrast rectangular red badge with bold white text "Thuốc kê toa". It must look like a professional health authority stamp.' : ''}

    ARTISTIC SPECIFICATIONS:
    - Setting: Ultra-modern medical laboratory or premium pharmacy showroom.
    - Lighting: Cinematic studio lighting, volumetric rays, soft bokeh background.
    - Product Display: Create a perfect 3D rendered version of the product box based on the provided image, sitting on a luxury podium.
    - Layout: ${data.aspectRatio === 'vertical' ? 'Vertical 9:16 Portrait' : 'Horizontal 16:9 Landscape'}.
    - Quality: Photorealistic, 8k resolution, masterpieces detail.

    OUTPUT: Return ONLY the English prompt string. No explanations.
    `;

    parts.push({ text: promptInput });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview', 
      contents: [{ role: 'user', parts: parts }]
    });

    return response.text || "Failed to generate prompt.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error; 
  }
};

/**
 * Processes a product image using Gemini 2.5 Flash Image for specialized tasks.
 */
export const processProductImageAI = async (
  base64Image: string, 
  mimeType: string, 
  task: 'remove-bg' | 'make-3d'
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const data = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;

  const prompts = {
    'remove-bg': "Please remove the background of this pharmaceutical product image. Return only the product on a pure, clean white background. Preserve all text and details on the packaging perfectly.",
    'make-3d': "Transform this product packaging into a high-quality, professional 3D isometric medicine box presentation. It should look like a real 3D box standing on a clean surface with soft shadows. Ensure the branding and text are perfectly readable."
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data, mimeType } },
          { text: prompts[task] }
        ]
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }

    throw new Error("AI did not return an edited image.");
  } catch (error) {
    console.error("Image Processing Error:", error);
    throw error;
  }
};

