            <label className="block text-sm font-medium text-slate-700 mb-1">Nhà Sản Xuất (Tiêu đề 4)</label>
            <div className="relative">
              <input type="text" value={activeProduct.manufacturer} onChange={(e) => handleChange(e, 'manufacturer')} placeholder="VD: Công ty DP APIMED" className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none" />
              <Factory className="w-4 h-4 text-slate-400 absolute left-3 top-2.5" />
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">Bối cảnh Poster & Mẫu</label>
            <div className="flex flex-wrap gap-2 mb-3">
              {PROMPT_TEMPLATES.map(t => (
                <button key={t.id} onClick={() => onChange(activeTab, 'description', t.text)} className="px-3 py-1.5 bg-slate-100 hover:bg-emerald-50 text-slate-600 border border-slate-200 rounded-full text-xs font-bold transition-all"><Quote className="w-3 h-3 inline mr-1" />{t.label}</button>
              ))}
            </div>
            <textarea value={activeProduct.description} onChange={(e) => handleChange(e, 'description')} placeholder="Ghi chú thêm về ánh sáng, phong cách..." className="w-full pl-4 pr-4 py-2 border border-slate-300 rounded-lg h-24 resize-none outline-none text-sm" />
          </div>
        </div>
      </div>

      <div className="p-6 border-t border-slate-100 bg-slate-50 rounded-b-xl">
        <button
          onClick={onSubmit}
          disabled={isProcessing}
          className={`w-full py-4 rounded-xl text-white font-bold shadow-lg transition-all flex items-center justify-center gap-2 uppercase tracking-wider
            ${isProcessing ? 'bg-slate-400 cursor-not-allowed' : 'bg-gradient-to-r from-blue-600 to-indigo-700 hover:shadow-xl active:scale-95'}`}
        >
          {isProcessing ? <Loader2 className="w-5 h-5 animate-spin" /> : <Sparkles className="w-5 h-5" />}
          {isProcessing ? 'Đang Thiết Kế Prompt...' : 'Tạo 3 Prompt Chuyên Nghiệp'}
        </button>
      </div>
    </div>
  );
};

import { AlertCircle, ArrowRight, Check, FileText, RefreshCw, Save, Search, Table, Upload, X } from 'lucide-react';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import * as XLSX from 'xlsx';
import { ExcelMapping, ProductData } from '../types';

interface ExcelImportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (products: ProductData[], rawData: any[], mapping: ExcelMapping) => void;
  onSave: (rawData: any[], mapping: ExcelMapping) => void;
  savedData?: any[];
  savedMapping?: ExcelMapping;
}

type ExcelRow = Record<string, any>;

const MAPPING_FIELDS: { key: keyof ExcelMapping; label: string }[] = [
  { key: 'name', label: 'Tên Thuốc' },
  { key: 'dosage', label: 'Hàm Lượng' },
  { key: 'packaging', label: 'Quy cách đóng gói' },
  { key: 'usage', label: 'Công Dụng' },
  { key: 'listPrice', label: 'Giá Niêm Yết' },
  { key: 'idecoPrice', label: 'Giá IDECO' },
  { key: 'manufacturer', label: 'Nhà Sản Xuất' },
];

export const ExcelImportModal: React.FC<ExcelImportModalProps> = ({ 
  isOpen, 
  onClose, 
  onImport, 
  onSave, 
  savedData = [], 
  savedMapping 
}) => {
  const [step, setStep] = useState<1 | 2>(1);
  const [data, setData] = useState<ExcelRow[]>([]);
  const [columns, setColumns] = useState<string[]>([]);
  const [mapping, setMapping] = useState<ExcelMapping>({
    name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: ''
  });
  const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());
  const [searchQuery, setSearchQuery] = useState('');
  const [isAutoLoaded, setIsAutoLoaded] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen) {
        if (savedData && savedData.length > 0) {
            setData(savedData);
            const cols = Object.keys(savedData[0]);
            setColumns(cols);
            if (savedMapping) setMapping(savedMapping);
            setStep(2);
            setIsAutoLoaded(true);
        } else {
            reset();
        }
    }
  }, [isOpen]); 

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const jsonData = XLSX.utils.sheet_to_json<ExcelRow>(ws, { header: 1 });

        if (jsonData.length > 0) {
          const headers = jsonData[0] as string[];
          const cleanHeaders = headers.map(h => String(h).trim());
          setColumns(cleanHeaders);
          const rows = XLSX.utils.sheet_to_json<ExcelRow>(ws, { header: cleanHeaders });
          setData(rows);

          const newMapping: ExcelMapping = { name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: '' };
          cleanHeaders.forEach(col => {
             const lower = col.toLowerCase();
             if (lower.includes('tên thuốc')) newMapping.name = col;
             else if (lower.includes('hàm lượng')) newMapping.dosage = col;
             else if (lower.includes('quy cách') || lower.includes('đóng gói')) newMapping.packaging = col;
             else if (lower.includes('công dụng')) newMapping.usage = col;
             else if (lower.includes('niêm yết')) newMapping.listPrice = col;
             else if (lower.includes('giá mua') || lower.includes('ideco')) newMapping.idecoPrice = col;
             else if (lower.includes('nhà sản xuất') || lower.includes('đơn vị sx')) newMapping.manufacturer = col;
          });
          setMapping(newMapping);
          setStep(2);
          setIsAutoLoaded(false);
          setSaveStatus('idle');
        }
      } catch (error) {
        alert("Lỗi đọc file Excel.");
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleMappingChange = (field: keyof ExcelMapping, column: string) => {
    setMapping(prev => ({ ...prev, [field]: column }));
    setSaveStatus('idle');
  };

  const toggleRowSelection = (originalIndex: number) => {
    const newSet = new Set(selectedIndices);
    if (newSet.has(originalIndex)) newSet.delete(originalIndex);
    else newSet.add(originalIndex);
    setSelectedIndices(newSet);
  };

  const filteredData = useMemo(() => {
    if (!searchQuery.trim()) return data.map((row, idx) => ({ row, originalIndex: idx }));
    const lowerQuery = searchQuery.toLowerCase();
    const searchCol = mapping.name || columns[0];
    return data
        .map((row, idx) => ({ row, originalIndex: idx }))
        .filter(({ row }) => {
            const val = row[searchCol];
            return val && String(val).toLowerCase().includes(lowerQuery);
        });
  }, [data, searchQuery, mapping.name, columns]);

  const handleSaveOnly = () => {
    if (data.length === 0) return;
    setSaveStatus('saving');
    onSave(data, mapping);
    setTimeout(() => {
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 3000);
    }, 500);
  };

  const handleApply = () => {
    const selectedRows = data.filter((_, idx) => selectedIndices.has(idx));
    if (selectedRows.length === 0) {
      alert("Vui lòng chọn ít nhất một sản phẩm.");
      return;
    }

    const formatPrice = (val: any, packagingVal: any) => {
        let p = '';
        if (typeof val === 'number') p = val.toLocaleString('vi-VN') + ' đồng';
        else {
            p = String(val || '');
            if (p && !p.toLowerCase().includes('đồng')) p += ' đồng';
        }

        if (packagingVal) {
            return `${p} / ${packagingVal}`;
        }
        return p;
    };

    const newProducts: ProductData[] = selectedRows.map((row, idx) => ({
      id: idx + 1,
      name: row[mapping.name] ? String(row[mapping.name]) : '',
      dosage: row[mapping.dosage] ? String(row[mapping.dosage]) : '',
      usage: row[mapping.usage] ? String(row[mapping.usage]) : '',
      listPrice: formatPrice(row[mapping.listPrice], row[mapping.packaging]),
      idecoPrice: formatPrice(row[mapping.idecoPrice], row[mapping.packaging]),
      manufacturer: row[mapping.manufacturer] ? String(row[mapping.manufacturer]) : '',
      isETC: false,
      description: '',
      aspectRatio: 'vertical'
    }));

    onImport(newProducts.slice(0, 3), data, mapping);
    onClose();
  };

  const reset = () => {
      setStep(1);
      setData([]);
      setColumns([]);
      setMapping({ name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: '' });
      setSelectedIndices(new Set());
      setSearchQuery('');
      setIsAutoLoaded(false);
      setSaveStatus('idle');
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden">
        <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
            <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <div className="p-2 bg-green-100 text-green-700 rounded-lg"><Table className="w-5 h-5" /></div>
                {step === 1 ? 'Nhập Dữ Liệu Từ Excel' : 'Chọn Sản Phẩm'}
            </h3>
            <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-2 hover:bg-slate-100 rounded-full"><X className="w-5 h-5" /></button>
        </div>
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
            {step === 1 ? (
                <div className="h-full flex flex-col items-center justify-center py-12 border-2 border-dashed border-slate-300 rounded-xl bg-slate-50 hover:bg-slate-100 transition-colors cursor-pointer"
                     onClick={() => fileInputRef.current?.click()}>
                    <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept=".xlsx, .xls" className="hidden" />
                    <Upload className="w-16 h-16 text-slate-300 mb-4" />
                    <p className="text-lg font-medium text-slate-600">Click để tải file Excel (.xlsx, .xls)</p>
                </div>
            ) : (
                <div className="space-y-6">
                    {isAutoLoaded && (
                        <div className="bg-blue-50 border border-blue-100 p-3 rounded-lg flex justify-between items-center text-sm text-blue-700">
                            <span className="flex items-center gap-2"><FileText className="w-4 h-4" /> Đã tự động tải dữ liệu từ bộ nhớ.</span>
                            <button onClick={reset} className="text-blue-600 hover:text-blue-800 font-semibold underline">Nhập file khác</button>
                        </div>
                    )}
                    <div className="bg-slate-50 p-4 rounded-xl border border-slate-200">
                        <div className="flex justify-between items-start mb-3">
                            <h4 className="font-semibold text-slate-700 flex items-center gap-2"><ArrowRight className="w-4 h-4 text-indigo-500" /> Bước 1: So chiếu cột</h4>
                            <button onClick={handleSaveOnly} className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border text-sm font-medium transition-all ${saveStatus === 'saved' ? 'bg-green-100 text-green-700 border-green-200' : 'bg-white text-slate-600 border-slate-300 hover:bg-slate-50'}`}>
                                {saveStatus === 'saved' ? <Check className="w-4 h-4" /> : <Save className="w-4 h-4" />} {saveStatus === 'saved' ? 'Đã Lưu!' : 'Lưu Dữ Liệu'}
                            </button>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {MAPPING_FIELDS.map(field => (
                                <div key={field.key}>
                                    <label className="block text-xs font-semibold text-slate-500 mb-1">{field.label}</label>
                                    <select className="w-full text-sm border-slate-300 rounded-lg shadow-sm focus:border-indigo-500 focus:ring-indigo-500" value={mapping[field.key] || ''} onChange={(e) => handleMappingChange(field.key, e.target.value)}>
                                        <option value="">-- Không chọn --</option>
                                        {columns.map(col => (<option key={col} value={col}>{col}</option>))}
                                    </select>
                                </div>
                            ))}
                        </div>
                    </div>
                    <div className="space-y-3">
                        <div className="flex flex-col md:flex-row justify-between items-end md:items-center gap-3">
                            <h4 className="font-semibold text-slate-700 flex items-center gap-2"><Check className="w-4 h-4 text-indigo-500" /> Bước 2: Chọn sản phẩm</h4>
                            <div className="relative w-full md:w-64">
                                <input type="text" placeholder="Tìm tên thuốc..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full pl-9 pr-3 py-1.5 text-sm border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none" />
                                <Search className="w-4 h-4 text-slate-400 absolute left-3 top-2" />
                            </div>
                        </div>
                        <div className="border border-slate-200 rounded-lg overflow-hidden">
                            <div className="overflow-x-auto max-h-[300px]">
                                <table className="w-full text-sm text-left">
                                    <thead className="bg-slate-100 text-slate-600 font-semibold sticky top-0 z-10">
                                        <tr><th className="p-3 w-10 text-center"><input type="checkbox" disabled /></th>{columns.map(col => (<th key={col} className="p-3 whitespace-nowrap">{col}</th>))}</tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100">
                                        {filteredData.length > 0 ? filteredData.map(({ row, originalIndex }) => (
                                            <tr key={originalIndex} className={`hover:bg-indigo-50 cursor-pointer transition-colors ${selectedIndices.has(originalIndex) ? 'bg-indigo-50' : ''}`} onClick={() => toggleRowSelection(originalIndex)}>
                                                <td className="p-3 text-center" onClick={(e) => e.stopPropagation()}><input type="checkbox" checked={selectedIndices.has(originalIndex)} onChange={() => toggleRowSelection(originalIndex)} className="rounded text-indigo-600 focus:ring-indigo-500" /></td>
                                                {columns.map(col => (<td key={`${originalIndex}-${col}`} className="p-3 whitespace-nowrap max-w-[200px] truncate">{row[col]}</td>))}
                                            </tr>
                                        )) : (<tr><td colSpan={columns.length + 1} className="p-8 text-center text-slate-500">Không tìm thấy kết quả.</td></tr>)}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
        <div className="px-6 py-4 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
            {step === 2 && (<button onClick={reset} className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-200 rounded-lg flex items-center gap-2"><RefreshCw className="w-4 h-4" /> Nhập File Khác</button>)}
            <button onClick={onClose} className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-200 rounded-lg">Hủy Bỏ</button>
            {step === 2 && (<button onClick={handleApply} disabled={selectedIndices.size === 0} className="px-6 py-2 text-sm font-bold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-md disabled:opacity-50 flex items-center gap-2"><Check className="w-4 h-4" /> Nhập Dữ Liệu</button>)}
        </div>
      </div>
    </div>
  );
};

// Add DollarSign to the imports from lucide-react
import { AlertCircle, Box, DollarSign, Download, Eraser, Factory, HeartPulse, Link as LinkIcon, Loader2, Monitor, Pill, Quote, Smartphone, Tag, Trash2, Upload } from 'lucide-react';
import React, { useMemo, useRef, useState } from 'react';
import { Sparkles } from 'lucide-react';
import { ExcelMapping, ProductData } from '../types';

interface ProductFormProps {
  products: ProductData[];
  activeTab: number;
  onTabChange: (id: number) => void;
  onChange: (id: number, field: keyof ProductData, value: string | boolean) => void;
  onImageUpload: (id: number, file: File) => void;
  onRemoveImage: (id: number) => void;
  onSubmit: () => void;
  onProcessImage: (id: number, task: 'remove-bg' | 'make-3d') => Promise<void>;
  isProcessing: boolean;
  isImageProcessing: boolean;
  masterLibrary?: any[];
  columnMapping?: ExcelMapping;
  onApplyLibraryProduct?: (id: number, libraryItem: any) => void;
}

const PROMPT_TEMPLATES = [
  { id: 'female_patient', label: '👩 Nữ bệnh nhân', text: 'Tạo poster chuyên nghiệp. Một bệnh nhân nữ trung niên người Việt Nam, tay cầm sản phẩm, tươi cười, tại phòng khám hiện đại.' },
  { id: 'doctor_consult', label: '👨‍⚕️ Bác sĩ tư vấn', text: 'Bác sĩ nam đang tư vấn, cầm hộp sản phẩm đưa về hướng bệnh nhân nam. Nền sáng, chuyên nghiệp.' },
  { id: 'packshot_3d', label: '📦 Packshot 3D', text: 'Chụp packshot sản phẩm 3D chuyên nghiệp, đặt trên bục sang trọng, ánh sáng cinematic.' }
];

export const ProductForm: React.FC<ProductFormProps> = ({ 
  products, activeTab, onTabChange, onChange, onImageUpload, onRemoveImage, onSubmit, onProcessImage,
  isProcessing, isImageProcessing, masterLibrary = [], columnMapping, onApplyLibraryProduct
}) => {
  const activeProduct = products.find(p => p.id === activeTab) || products[0];
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [imageUrlInput, setImageUrlInput] = useState('');
  const [isUrlLoading, setIsUrlLoading] = useState(false);

  const suggestions = useMemo(() => {
    if (!activeProduct.name || !masterLibrary.length || !columnMapping?.name) return [];
    const lowerInput = activeProduct.name.toLowerCase();
    const nameKey = columnMapping.name;
    return masterLibrary
        .filter(item => item[nameKey] && String(item[nameKey]).toLowerCase().includes(lowerInput))
        .slice(0, 5);
  }, [activeProduct.name, masterLibrary, columnMapping]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>, field: keyof ProductData) => {
    onChange(activeTab, field, e.target.value);
    if (field === 'name') setShowSuggestions(true);
  };

  const handleSuggestionClick = (item: any) => {
      onApplyLibraryProduct?.(activeTab, item);
      setShowSuggestions(false);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) onImageUpload(activeTab, e.target.files[0]);
  };

  const handleUrlLoad = async () => {
    if (!imageUrlInput.trim()) return;
    setIsUrlLoading(true);
    try {
      const response = await fetch(imageUrlInput);
      const blob = await response.blob();
      const file = new File([blob], "image_from_url.png", { type: blob.type });
      onImageUpload(activeTab, file);
      setImageUrlInput('');
    } catch (e) {
      alert("Lỗi tải ảnh. Vui lòng thử lại hoặc tải ảnh về máy rồi upload thủ công.");
    } finally {
      setIsUrlLoading(false);
    }
  };

  const downloadProductImage = () => {
    if (!activeProduct.imageBase64) return;
    const link = document.createElement('a');
    link.href = activeProduct.imageBase64;
    const fileName = activeProduct.name ? activeProduct.name.trim().replace(/\s+/g, '_') : `Product_${activeTab}`;
    link.download = `${fileName}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="bg-white rounded-xl shadow-lg flex flex-col h-full border border-slate-200">
      <div className="flex border-b border-slate-200 bg-slate-50 rounded-t-xl overflow-hidden">
        {products.map((p) => (
          <button
            key={p.id}
            onClick={() => onTabChange(p.id)}
            className={`flex-1 py-3 text-sm font-semibold transition-all border-r border-slate-200 last:border-r-0
              ${activeTab === p.id ? 'bg-white text-emerald-700 border-t-2 border-t-emerald-500 shadow-sm' : 'text-slate-500 hover:bg-slate-100'}`}
          >
            Sản phẩm {p.id}
          </button>
        ))}
      </div>

      <div className="p-6 md:p-8 flex-1 overflow-y-auto custom-scrollbar">
        <div className="flex items-center justify-between mb-6 gap-3">
            <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                <Pill className="w-5 h-5 text-emerald-600" /> Thông Tin SP {activeTab}
            </h2>
            <div className="bg-slate-100 p-1 rounded-lg flex border border-slate-200">
                <button onClick={() => onChange(activeTab, 'aspectRatio', 'vertical')} className={`px-3 py-1 text-xs font-bold rounded-md flex items-center gap-1 transition-all ${activeProduct.aspectRatio === 'vertical' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}><Smartphone className="w-3 h-3" /> Dọc</button>
                <button onClick={() => onChange(activeTab, 'aspectRatio', 'horizontal')} className={`px-3 py-1 text-xs font-bold rounded-md flex items-center gap-1 transition-all ${activeProduct.aspectRatio === 'horizontal' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}><Monitor className="w-3 h-3" /> Ngang</button>
            </div>
        </div>

        <div className="space-y-5">
          {/* Image Area */}
          <div className="border-2 border-dashed border-slate-300 rounded-lg p-4 bg-slate-50/50 hover:bg-white hover:border-emerald-400 transition-colors relative group">
            <div className="flex justify-between items-center mb-2">
                <span className="text-sm font-medium text-slate-700">Ảnh Sản Phẩm (Gốc/Xử lý)</span>
                {activeProduct.imageBase64 && (
                    <div className="flex gap-2">
                        <button onClick={downloadProductImage} className="text-xs text-blue-600 font-bold flex items-center gap-1 hover:underline" title="Tải ảnh sản phẩm về máy">
                            <Download className="w-3 h-3" /> Tải về
                        </button>
                        <button onClick={() => onRemoveImage(activeTab)} className="text-xs text-red-500 font-bold flex items-center gap-1 hover:underline">
                            <Trash2 className="w-3 h-3" /> Xóa
                        </button>
                    </div>
                )}
            </div>

            <input type="file" accept="image/*" ref={fileInputRef} onChange={handleFileChange} className="hidden" />

            {!activeProduct.imageBase64 ? (
              <div className="space-y-4">
                  <div onClick={() => fileInputRef.current?.click()} className="cursor-pointer flex flex-col items-center justify-center py-6 text-slate-400">
                    <Upload className="w-8 h-8 mb-2 opacity-50" />
                    <p className="text-sm">Click để tải ảnh lên</p>
                  </div>
                  <div className="flex items-center gap-2 border-t border-slate-200 pt-4">
                     <LinkIcon className="w-4 h-4 text-slate-400" />
                     <input 
                        type="text" placeholder="Dán link ảnh (URL) vào đây..."
                        className="flex-1 text-xs border border-slate-300 rounded px-3 py-2 outline-none"
                        value={imageUrlInput} onChange={(e) => setImageUrlInput(e.target.value)}
                     />
                     <button onClick={handleUrlLoad} disabled={!imageUrlInput.trim() || isUrlLoading} className="text-xs bg-emerald-600 text-white px-4 py-2 rounded font-bold disabled:opacity-50">
                        {isUrlLoading ? '...' : 'Tải'}
                     </button>
                  </div>
              </div>
            ) : (
