import { GoogleGenAI } from "@google/genai";
import { ProductData } from "../types";

/**
 * Generates an optimized image generation prompt based on product data.
 */
export const generateOptimizedPrompt = async (data: ProductData): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const parts: any[] = [];

    if (data.imageBase64 && data.mimeType) {
      const base64Data = data.imageBase64.split(',')[1];
      parts.push({
        inlineData: {
          mimeType: data.mimeType,
          data: base64Data
        }
      });
    }

    const promptInput = `
    Role: World-Class Pharmaceutical Advertising Creative Director.
    Task: Write a high-conversion, professional English text-to-image prompt for a premium medicine poster.

    CONTENT HIERARCHY (ABSOLUTE PRIORITY):
    1. BRAND RECOGNITION (Title 1): "${data.name}".
       - VISUAL INSTRUCTION: Deeply analyze the provided product image. Use the exact branding, colors, and logo style seen on the physical package. 
       - Render "${data.name}" in large, luxurious 3D typography at the top.

    2. PRIMARY SALES HOOK (Title 3 - IDECO Price): "${data.idecoPrice}".
       - THIS IS THE MOST IMPORTANT TEXT. It must be the visual centerpiece of the poster.
       - Render this in a massive, glowing font with a premium 3D effect (liquid gold, vibrant neon emerald, or glossy 3D chrome). 
       - Place it inside an eye-catching, high-contrast promotional badge or a floating ribbon. It must be impossible to ignore.

    3. COMPARISON PRICE (Title 2 - List Price): "${data.listPrice}".
       - Position this near the IDECO price but significantly smaller. Use a cleaner, simpler style to create contrast and highlight the savings.

    4. PRODUCT DETAILS: "${data.dosage}" and "${data.usage}".
       - Neatly integrated into the layout as secondary supporting information.

    5. COMPLIANCE FOOTER (Title 4 - Manufacturer): "Nhà sản xuất bởi: ${data.manufacturer}".
       - Render this in a professional, clean font at the very bottom.

    ${data.isETC ? '6. REGULATORY BADGE: In the ABSOLUTE TOP-LEFT CORNER, render a clear red rectangular badge with the white bold text "Thuốc kê toa". This is a mandatory regulatory requirement and must be clearly legible.' : ''}

    ARTISTIC SPECIFICATIONS:
    - Context: A high-end, futuristic pharmacy laboratory or a minimalist professional clinical setting.
    - Lighting: Cinematic studio lighting, soft shadows, volumetric light rays, and professional product photography bokeh.
    - Product Shot: Create a photorealistic 3D render of the product box (based on the provided image) sitting on a glass podium or a clean surgical tray.
    - Style: Photorealistic, 8k resolution, Masterpiece quality.
    - Aspect Ratio: ${data.aspectRatio === 'vertical' ? 'Vertical 9:16' : 'Horizontal 16:9'}.

    OUTPUT: ONLY the English prompt string. No conversational text.
    `;

    parts.push({ text: promptInput });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview', 
      contents: [{ role: 'user', parts: parts }]
    });

    return response.text || "Failed to generate prompt.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error; 
  }
};

/**
 * Processes a product image using Gemini 2.5 Flash Image for specialized tasks.
 */
export const processProductImageAI = async (
  base64Image: string, 
  mimeType: string, 
  task: 'remove-bg' | 'make-3d'
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const data = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;

  const prompts = {
    'remove-bg': "Please remove the background of this pharmaceutical product image. Return only the product on a pure, clean white background. Preserve all text and details on the packaging perfectly.",
    'make-3d': "Transform this product packaging into a high-quality, professional 3D isometric medicine box presentation. It should look like a real 3D box standing on a clean surface with soft shadows. Ensure the branding and text are perfectly readable."
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data, mimeType } },
          { text: prompts[task] }
        ]
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }

    throw new Error("AI did not return an edited image.");
  } catch (error) {
    console.error("Image Processing Error:", error);
    throw error;
  }
};

import { AlertCircle, ArrowRight, Check, FileText, RefreshCw, Save, Search, Table, Upload, X } from 'lucide-react';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import * as XLSX from 'xlsx';
import { ExcelMapping, ProductData } from '../types';

interface ExcelImportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (products: ProductData[], rawData: any[], mapping: ExcelMapping) => void;
  onSave: (rawData: any[], mapping: ExcelMapping) => void;
  savedData?: any[];
  savedMapping?: ExcelMapping;
}

type ExcelRow = Record<string, any>;

const MAPPING_FIELDS: { key: keyof ExcelMapping; label: string }[] = [
  { key: 'name', label: 'Tên Thuốc' },
  { key: 'dosage', label: 'Hàm Lượng' },
  { key: 'packaging', label: 'Quy cách đóng gói' },
  { key: 'usage', label: 'Công Dụng' },
  { key: 'listPrice', label: 'Giá Niêm Yết' },
  { key: 'idecoPrice', label: 'Giá IDECO' },
  { key: 'manufacturer', label: 'Nhà Sản Xuất' },
];

export const ExcelImportModal: React.FC<ExcelImportModalProps> = ({ 
  isOpen, 
  onClose, 
  onImport, 
  onSave, 
  savedData = [], 
  savedMapping 
}) => {
  const [step, setStep] = useState<1 | 2>(1);
  const [data, setData] = useState<ExcelRow[]>([]);
  const [columns, setColumns] = useState<string[]>([]);
  const [mapping, setMapping] = useState<ExcelMapping>({
    name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: ''
  });
  const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());
  const [searchQuery, setSearchQuery] = useState('');
  const [isAutoLoaded, setIsAutoLoaded] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen) {
        if (savedData && savedData.length > 0) {
            setData(savedData);
            const cols = Object.keys(savedData[0]);
            setColumns(cols);
            if (savedMapping) setMapping(savedMapping);
            setStep(2);
            setIsAutoLoaded(true);
        } else {
            reset();
        }
    }
  }, [isOpen]); 

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const jsonData = XLSX.utils.sheet_to_json<ExcelRow>(ws, { header: 1 });

        if (jsonData.length > 0) {
          const headers = jsonData[0] as string[];
          const cleanHeaders = headers.map(h => String(h).trim());
          setColumns(cleanHeaders);
          const rows = XLSX.utils.sheet_to_json<ExcelRow>(ws, { header: cleanHeaders });
          setData(rows);

          const newMapping: ExcelMapping = { name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: '' };
          cleanHeaders.forEach(col => {
             const lower = col.toLowerCase();
             if (lower.includes('tên thuốc')) newMapping.name = col;
             else if (lower.includes('hàm lượng')) newMapping.dosage = col;
             else if (lower.includes('quy cách') || lower.includes('đóng gói')) newMapping.packaging = col;
             else if (lower.includes('công dụng')) newMapping.usage = col;
             else if (lower.includes('niêm yết')) newMapping.listPrice = col;
             else if (lower.includes('giá mua') || lower.includes('ideco')) newMapping.idecoPrice = col;
             else if (lower.includes('nhà sản xuất') || lower.includes('đơn vị sx')) newMapping.manufacturer = col;
          });
          setMapping(newMapping);
          setStep(2);
          setIsAutoLoaded(false);
          setSaveStatus('idle');
        }
      } catch (error) {
        alert("Lỗi đọc file Excel.");
      }
    };
    reader.readAsDataString(file);
  };

  const handleMappingChange = (field: keyof ExcelMapping, column: string) => {
    setMapping(prev => ({ ...prev, [field]: column }));
    setSaveStatus('idle');
  };

  const toggleRowSelection = (originalIndex: number) => {
    const newSet = new Set(selectedIndices);
    if (newSet.has(originalIndex)) newSet.delete(originalIndex);
    else newSet.add(originalIndex);
    setSelectedIndices(newSet);
  };

  const filteredData = useMemo(() => {
    if (!searchQuery.trim()) return data.map((row, idx) => ({ row, originalIndex: idx }));
    const lowerQuery = searchQuery.toLowerCase();
    const searchCol = mapping.name || columns[0];
    return data
        .map((row, idx) => ({ row, originalIndex: idx }))
        .filter(({ row }) => {
            const val = row[searchCol];
            return val && String(val).toLowerCase().includes(lowerQuery);
        });
  }, [data, searchQuery, mapping.name, columns]);

  const handleSaveOnly = () => {
    if (data.length === 0) return;
    setSaveStatus('saving');
    onSave(data, mapping);
    setTimeout(() => {
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 3000);
    }, 500);
  };

  const handleApply = () => {
    const selectedRows = data.filter((_, idx) => selectedIndices.has(idx));
    if (selectedRows.length === 0) {
      alert("Vui lòng chọn ít nhất một sản phẩm.");
      return;
    }

    const formatPrice = (val: any, packagingVal: any) => {
        let p = '';
        if (typeof val === 'number') {
            p = val.toLocaleString('vi-VN') + ' đồng';
        } else {
            p = String(val || '');
            if (p && !p.toLowerCase().includes('đồng')) {
                // If it looks like a number but is a string
                const num = parseFloat(p.replace(/[^0-9.-]+/g,""));
                if (!isNaN(num)) {
                    p = num.toLocaleString('vi-VN') + ' đồng';
                } else {
                    p += ' đồng';
                }
            }
        }

        if (packagingVal) {
            const packStr = String(packagingVal).trim();
            if (packStr) {
                return `${p}/ ${packStr}`;
            }
        }
        return p;
    };

    const newProducts: ProductData[] = selectedRows.map((row, idx) => ({
      id: idx + 1,
      name: row[mapping.name] ? String(row[mapping.name]) : '',
      dosage: row[mapping.dosage] ? String(row[mapping.dosage]) : '',
      usage: row[mapping.usage] ? String(row[mapping.usage]) : '',
      listPrice: formatPrice(row[mapping.listPrice], row[mapping.packaging]),
      idecoPrice: formatPrice(row[mapping.idecoPrice], row[mapping.packaging]),
      manufacturer: row[mapping.manufacturer] ? String(row[mapping.manufacturer]) : '',
      isETC: false,
      description: '',
      aspectRatio: 'vertical'
    }));

    onImport(newProducts.slice(0, 3), data, mapping);
    onClose();
  };

  const reset = () => {
      setStep(1);
      setData([]);
      setColumns([]);
      setMapping({ name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: '' });
      setSelectedIndices(new Set());
      setSearchQuery('');
      setIsAutoLoaded(false);
      setSaveStatus('idle');
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden">
        <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
            <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <div className="p-2 bg-green-100 text-green-700 rounded-lg"><Table className="w-5 h-5" /></div>
                {step === 1 ? 'Nhập Dữ Liệu Từ Excel' : 'Chọn Sản Phẩm'}
            </h3>
            <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-2 hover:bg-slate-100 rounded-full"><X className="w-5 h-5" /></button>
        </div>
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
            {step === 1 ? (
                <div className="h-full flex flex-col items-center justify-center py-12 border-2 border-dashed border-slate-300 rounded-xl bg-slate-50 hover:bg-slate-100 transition-colors cursor-pointer"
                     onClick={() => fileInputRef.current?.click()}>
                    <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept=".xlsx, .xls" className="hidden" />
                    <Upload className="w-16 h-16 text-slate-300 mb-4" />
                    <p className="text-lg font-medium text-slate-600">Click để tải file Excel (.xlsx, .xls)</p>
                </div>
            ) : (
                <div className="space-y-6">
                    {isAutoLoaded && (
                        <div className="bg-blue-50 border border-blue-100 p-3 rounded-lg flex justify-between items-center text-sm text-blue-700">
                            <span className="flex items-center gap-2"><FileText className="w-4 h-4" /> Đã tự động tải dữ liệu từ bộ nhớ.</span>
                            <button onClick={reset} className="text-blue-600 hover:text-blue-800 font-semibold underline">Nhập file khác</button>
                        </div>
                    )}
                    <div className="bg-slate-50 p-4 rounded-xl border border-slate-200">
                        <div className="flex justify-between items-start mb-3">
                            <h4 className="font-semibold text-slate-700 flex items-center gap-2"><ArrowRight className="w-4 h-4 text-indigo-500" /> Bước 1: So chiếu cột</h4>
                            <button onClick={handleSaveOnly} className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border text-sm font-medium transition-all ${saveStatus === 'saved' ? 'bg-green-100 text-green-700 border-green-200' : 'bg-white text-slate-600 border-slate-300 hover:bg-slate-50'}`}>
                                {saveStatus === 'saved' ? <Check className="w-4 h-4" /> : <Save className="w-4 h-4" />} {saveStatus === 'saved' ? 'Đã Lưu!' : 'Lưu Dữ Liệu'}
                            </button>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {MAPPING_FIELDS.map(field => (
                                <div key={field.key}>
                                    <label className="block text-xs font-semibold text-slate-500 mb-1">{field.label}</label>
                                    <select className="w-full text-sm border-slate-300 rounded-lg shadow-sm focus:border-indigo-500 focus:ring-indigo-500" value={mapping[field.key] || ''} onChange={(e) => handleMappingChange(field.key, e.target.value)}>
                                        <option value="">-- Không chọn --</option>
                                        {columns.map(col => (<option key={col} value={col}>{col}</option>))}
                                    </select>
                                </div>
                            ))}
                        </div>
                    </div>
                    <div className="space-y-3">
                        <div className="flex flex-col md:flex-row justify-between items-end md:items-center gap-3">
                            <h4 className="font-semibold text-slate-700 flex items-center gap-2"><Check className="w-4 h-4 text-indigo-500" /> Bước 2: Chọn sản phẩm</h4>
