                                                {columns.map(col => (<td key={`${originalIndex}-${col}`} className="p-3 whitespace-nowrap max-w-[200px] truncate">{row[col]}</td>))}
                                            </tr>
                                        )) : (<tr><td colSpan={columns.length + 1} className="p-8 text-center text-slate-500">Không tìm thấy kết quả.</td></tr>)}
                                    </tbody>
