import { AlertCircle, ArrowRight, Check, FileText, RefreshCw, Save, Search, Table, Upload, X } from 'lucide-react';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import * as XLSX from 'xlsx';
import { ExcelMapping, ProductData } from '../types';

interface ExcelImportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (products: ProductData[], rawData: any[], mapping: ExcelMapping) => void;
  onSave: (rawData: any[], mapping: ExcelMapping) => void;
  savedData?: any[];
  savedMapping?: ExcelMapping;
}

type ExcelRow = Record<string, any>;

const MAPPING_FIELDS: { key: keyof ExcelMapping; label: string }[] = [
  { key: 'name', label: 'Tên Thuốc' },
  { key: 'dosage', label: 'Hàm Lượng' },
  { key: 'packaging', label: 'Quy cách đóng gói' },
  { key: 'usage', label: 'Công Dụng' },
  { key: 'listPrice', label: 'Giá Niêm Yết' },
  { key: 'idecoPrice', label: 'Giá IDECO' },
  { key: 'manufacturer', label: 'Nhà Sản Xuất' },
];

export const ExcelImportModal: React.FC<ExcelImportModalProps> = ({ 
  isOpen, 
  onClose, 
  onImport, 
  onSave, 
  savedData = [], 
  savedMapping 
}) => {
  const [step, setStep] = useState<1 | 2>(1);
  const [data, setData] = useState<ExcelRow[]>([]);
  const [columns, setColumns] = useState<string[]>([]);
  const [mapping, setMapping] = useState<ExcelMapping>({
    name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: ''
  });
  const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());
  const [searchQuery, setSearchQuery] = useState('');
  const [isAutoLoaded, setIsAutoLoaded] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen) {
        if (savedData && savedData.length > 0) {
            setData(savedData);
            const cols = Object.keys(savedData[0]);
            setColumns(cols);
            if (savedMapping) setMapping(savedMapping);
            setStep(2);
            setIsAutoLoaded(true);
        } else {
            reset();
        }
    }
  }, [isOpen]); 

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const jsonData = XLSX.utils.sheet_to_json<ExcelRow>(ws, { header: 1 });

        if (jsonData.length > 0) {
          const headers = jsonData[0] as string[];
          const cleanHeaders = headers.map(h => String(h).trim());
          setColumns(cleanHeaders);
          const rows = XLSX.utils.sheet_to_json<ExcelRow>(ws, { header: cleanHeaders });
          setData(rows);

          const newMapping: ExcelMapping = { name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: '' };
          cleanHeaders.forEach(col => {
             const lower = col.toLowerCase();
             if (lower.includes('tên thuốc')) newMapping.name = col;
             else if (lower.includes('hàm lượng')) newMapping.dosage = col;
             else if (lower.includes('quy cách') || lower.includes('đóng gói')) newMapping.packaging = col;
             else if (lower.includes('công dụng')) newMapping.usage = col;
             else if (lower.includes('niêm yết')) newMapping.listPrice = col;
             else if (lower.includes('giá mua') || lower.includes('ideco')) newMapping.idecoPrice = col;
             else if (lower.includes('nhà sản xuất') || lower.includes('đơn vị sx')) newMapping.manufacturer = col;
          });
          setMapping(newMapping);
          setStep(2);
          setIsAutoLoaded(false);
          setSaveStatus('idle');
        }
      } catch (error) {
        alert("Lỗi đọc file Excel.");
      }
    };
    // FIX: Changed from readAsDataString to readAsBinaryString to properly handle binary Excel file data.
    reader.readAsBinaryString(file);
  };

  const handleMappingChange = (field: keyof ExcelMapping, column: string) => {
    setMapping(prev => ({ ...prev, [field]: column }));
    setSaveStatus('idle');
  };

  const toggleRowSelection = (originalIndex: number) => {
    const newSet = new Set(selectedIndices);
    if (newSet.has(originalIndex)) newSet.delete(originalIndex);
    else newSet.add(originalIndex);
    setSelectedIndices(newSet);
  };

  const filteredData = useMemo(() => {
    if (!searchQuery.trim()) return data.map((row, idx) => ({ row, originalIndex: idx }));
    const lowerQuery = searchQuery.toLowerCase();
    const searchCol = mapping.name || columns[0];
    return data
        .map((row, idx) => ({ row, originalIndex: idx }))
        .filter(({ row }) => {
            const val = row[searchCol];
            return val && String(val).toLowerCase().includes(lowerQuery);
        });
  }, [data, searchQuery, mapping.name, columns]);

  const handleSaveOnly = () => {
    if (data.length === 0) return;
    setSaveStatus('saving');
    onSave(data, mapping);
    setTimeout(() => {
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 3000);
    }, 500);
  };

  const handleApply = () => {
    const selectedRows = data.filter((_, idx) => selectedIndices.has(idx));
    if (selectedRows.length === 0) {
      alert("Vui lòng chọn ít nhất một sản phẩm.");
      return;
    }

    const formatPrice = (val: any, packagingVal: any) => {
        let p = '';
        if (typeof val === 'number') {
            p = val.toLocaleString('vi-VN') + ' đồng';
        } else {
            p = String(val || '');
            if (p && !p.toLowerCase().includes('đồng')) {
                // If it looks like a number but is a string
                const num = parseFloat(p.replace(/[^0-9.-]+/g,""));
                if (!isNaN(num)) {
                    p = num.toLocaleString('vi-VN') + ' đồng';
                } else {
                    p += ' đồng';
                }
            }
        }

        if (packagingVal) {
            const packStr = String(packagingVal).trim();
            if (packStr) {
                return `${p}/ ${packStr}`;
            }
        }
        return p;
    };

    const newProducts: ProductData[] = selectedRows.map((row, idx) => ({
      id: idx + 1,
      name: row[mapping.name] ? String(row[mapping.name]) : '',
      dosage: row[mapping.dosage] ? String(row[mapping.dosage]) : '',
      usage: row[mapping.usage] ? String(row[mapping.usage]) : '',
      listPrice: formatPrice(row[mapping.listPrice], row[mapping.packaging]),
      idecoPrice: formatPrice(row[mapping.idecoPrice], row[mapping.packaging]),
      manufacturer: row[mapping.manufacturer] ? String(row[mapping.manufacturer]) : '',
      isETC: false,
      description: '',
      aspectRatio: 'vertical'
    }));

    onImport(newProducts.slice(0, 3), data, mapping);
    onClose();
  };

  const reset = () => {
      setStep(1);
      setData([]);
      setColumns([]);
      setMapping({ name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: '' });
      setSelectedIndices(new Set());
      setSearchQuery('');
      setIsAutoLoaded(false);
      setSaveStatus('idle');
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden">
        <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
            <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <div className="p-2 bg-green-100 text-green-700 rounded-lg"><Table className="w-5 h-5" /></div>
                {step === 1 ? 'Nhập Dữ Liệu Từ Excel' : 'Chọn Sản Phẩm'}
            </h3>
            <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-2 hover:bg-slate-100 rounded-full"><X className="w-5 h-5" /></button>
        </div>
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
            {step === 1 ? (
                <div className="h-full flex flex-col items-center justify-center py-12 border-2 border-dashed border-slate-300 rounded-xl bg-slate-50 hover:bg-slate-100 transition-colors cursor-pointer"
                     onClick={() => fileInputRef.current?.click()}>
                    <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept=".xlsx, .xls" className="hidden" />
                    <Upload className="w-16 h-16 text-slate-300 mb-4" />
                    <p className="text-lg font-medium text-slate-600">Click để tải file Excel (.xlsx, .xls)</p>
                </div>
            ) : (
                <div className="space-y-6">
                    {isAutoLoaded && (
                        <div className="bg-blue-50 border border-blue-100 p-3 rounded-lg flex justify-between items-center text-sm text-blue-700">
                            <span className="flex items-center gap-2"><FileText className="w-4 h-4" /> Đã tự động tải dữ liệu từ bộ nhớ.</span>
                            <button onClick={reset} className="text-blue-600 hover:text-blue-800 font-semibold underline">Nhập file khác</button>
                        </div>
                    )}
                    <div className="bg-slate-50 p-4 rounded-xl border border-slate-200">
                        <div className="flex justify-between items-start mb-3">
                            <h4 className="font-semibold text-slate-700 flex items-center gap-2"><ArrowRight className="w-4 h-4 text-indigo-500" /> Bước 1: So chiếu cột</h4>
                            <button onClick={handleSaveOnly} className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border text-sm font-medium transition-all ${saveStatus === 'saved' ? 'bg-green-100 text-green-700 border-green-200' : 'bg-white text-slate-600 border-slate-300 hover:bg-slate-50'}`}>
                                {saveStatus === 'saved' ? <Check className="w-4 h-4" /> : <Save className="w-4 h-4" />} {saveStatus === 'saved' ? 'Đã Lưu!' : 'Lưu Dữ Liệu'}
                            </button>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {MAPPING_FIELDS.map(field => (
                                <div key={field.key}>
                                    <label className="block text-xs font-semibold text-slate-500 mb-1">{field.label}</label>
                                    <select className="w-full text-sm border-slate-300 rounded-lg shadow-sm focus:border-indigo-500 focus:ring-indigo-500" value={mapping[field.key] || ''} onChange={(e) => handleMappingChange(field.key, e.target.value)}>
                                        <option value="">-- Không chọn --</option>
                                        {columns.map(col => (<option key={col} value={col}>{col}</option>))}
                                    </select>
                                </div>
                            ))}
                        </div>
                    </div>
                    <div className="space-y-3">
                        <div className="flex flex-col md:flex-row justify-between items-end md:items-center gap-3">
                            <h4 className="font-semibold text-slate-700 flex items-center gap-2"><Check className="w-4 h-4 text-indigo-500" /> Bước 2: Chọn sản phẩm</h4>
                            <div className="relative w-full md:w-64">
                                <input type="text" placeholder="Tìm tên thuốc..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full pl-9 pr-3 py-1.5 text-sm border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none" />
                                <Search className="w-4 h-4 text-slate-400 absolute left-3 top-2" />
                            </div>
                        </div>
                        <div className="border border-slate-200 rounded-lg overflow-hidden">
                            <div className="overflow-x-auto max-h-[300px]">
                                <table className="w-full text-sm text-left">
                                    <thead className="bg-slate-100 text-slate-600 font-semibold sticky top-0 z-10">
                                        <tr><th className="p-3 w-10 text-center"><input type="checkbox" disabled /></th>{columns.map(col => (<th key={col} className="p-3 whitespace-nowrap">{col}</th>))}</tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100">
                                        {filteredData.length > 0 ? filteredData.map(({ row, originalIndex }) => (
                                            <tr key={originalIndex} className={`hover:bg-indigo-50 cursor-pointer transition-colors ${selectedIndices.has(originalIndex) ? 'bg-indigo-50' : ''}`} onClick={() => toggleRowSelection(originalIndex)}>
                                                <td className="p-3 text-center" onClick={(e) => e.stopPropagation()}><input type="checkbox" checked={selectedIndices.has(originalIndex)} onChange={() => toggleRowSelection(originalIndex)} className="rounded text-indigo-600 focus:ring-indigo-500" /></td>
                                                {columns.map(col => (<td key={`${originalIndex}-${col}`} className="p-3 whitespace-nowrap max-w-[200px] truncate">{row[col]}</td>))}
                                            </tr>
                                        )) : (<tr><td colSpan={columns.length + 1} className="p-8 text-center text-slate-500">Không tìm thấy kết quả.</td></tr>)}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
        <div className="px-6 py-4 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
            {step === 2 && (<button onClick={reset} className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-200 rounded-lg flex items-center gap-2"><RefreshCw className="w-4 h-4" /> Nhập File Khác</button>)}
            <button onClick={onClose} className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-200 rounded-lg">Hủy Bỏ</button>
            {step === 2 && (<button onClick={handleApply} disabled={selectedIndices.size === 0} className="px-6 py-2 text-sm font-bold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-md disabled:opacity-50 flex items-center gap-2"><Check className="w-4 h-4" /> Nhập Dữ Liệu</button>)}
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { ProductData } from "../types";

/**
 * Generates an optimized image generation prompt based on product data.
 */
export const generateOptimizedPrompt = async (data: ProductData): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const parts: any[] = [];

    if (data.imageBase64 && data.mimeType) {
      const base64Data = data.imageBase64.split(',')[1];
      parts.push({
        inlineData: {
          mimeType: data.mimeType,
          data: base64Data
        }
      });
    }

    const promptInput = `
    Role: World-Class Pharmaceutical Creative Director.
    Task: Write a high-end English text-to-image prompt for a premium medical poster.

    DATA INPUTS (MUST BE RENDERED EXACTLY):
    - Title 1 (Drug Name): "${data.name}"
    - Title 2 (List Price): "${data.listPrice}"
    - Title 3 (SPECIAL IDECO PRICE): "${data.idecoPrice}"
    - Title 4 (Manufacturer): "Nhà sản xuất bởi: ${data.manufacturer}"
    - Specs: ${data.dosage} | ${data.usage}
    - Is Prescription (ETC): ${data.isETC ? 'YES' : 'NO'}

    CRITICAL DESIGN INSTRUCTIONS:
    1. BRAND ACCURACY: Analyze the attached image first. Identify the EXACT product name and logo style from the physical box. Use "${data.name}" as the primary 3D title at the top center.
    2. THE VISUAL HOOK (IDECO PRICE): Render "${data.idecoPrice}" in a massive, high-contrast, glowing 3D style. Use vibrant colors like 'Emerald Green' or 'Electric Gold'. Place it inside a premium floating glass badge or a shiny 3D ribbon. This MUST be the most eye-catching element on the poster.
    3. PRICE COMPARISON: Render the list price "${data.listPrice}" in a much smaller, clean, minimalist font nearby to highlight the incredible value of the IDECO price.
    4. REGULATORY BADGE: ${data.isETC ? 'In the ABSOLUTE TOP-LEFT CORNER, render a clear, formal red rectangular badge with bold white text "Thuốc kê toa". It must look like a mandatory government health label.' : ''}
    5. FOOTER: Place the text "Nhà sản xuất bởi: ${data.manufacturer}" elegantly at the very bottom edge.

    ARTISTIC STYLE:
    - Background: Clean, modern pharmaceutical laboratory with soft cinematic lighting and shallow depth of field (bokeh).
    - Product: A hyper-realistic 3D render of the actual product box from the photo, standing on a white pedestal.
    - Quality: Photorealistic 8k, professional product photography, sharp details.
    - Aspect Ratio: ${data.aspectRatio === 'vertical' ? '9:16 Portrait' : '16:9 Landscape'}.

    OUTPUT: Return ONLY the detailed English prompt. No conversation.
    `;

    parts.push({ text: promptInput });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview', 
      contents: [{ role: 'user', parts: parts }]
    });

    return response.text || "Failed to generate prompt.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error; 
  }
};

/**
 * Processes a product image using Gemini 2.5 Flash Image.
 */
export const processProductImageAI = async (
  base64Image: string, 
  mimeType: string, 
  task: 'remove-bg' | 'make-3d'
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const data = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;

  const prompts = {
    'remove-bg': "Remove the background. Keep only the product on pure white. Do not alter labels.",
    'make-3d': "Transform this product photo into a professional 3D packshot on a clean surface."
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data, mimeType } },
          { text: prompts[task] }
        ]
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }
    throw new Error("AI did not return an image.");
  } catch (error) {
    console.error("Image Processing Error:", error);
    throw error;
  }
};

import { AlertCircle, ArrowRight, Check, FileText, RefreshCw, Save, Search, Table, Upload, X } from 'lucide-react';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import * as XLSX from 'xlsx';
import { ExcelMapping, ProductData } from '../types';

interface ExcelImportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (products: ProductData[], rawData: any[], mapping: ExcelMapping) => void;
  onSave: (rawData: any[], mapping: ExcelMapping) => void;
  savedData?: any[];
  savedMapping?: ExcelMapping;
}

type ExcelRow = Record<string, any>;

const MAPPING_FIELDS: { key: keyof ExcelMapping; label: string }[] = [
  { key: 'name', label: 'Tên Thuốc' },
  { key: 'dosage', label: 'Hàm Lượng' },
  { key: 'packaging', label: 'Quy cách đóng gói' },
  { key: 'usage', label: 'Công Dụng' },
  { key: 'listPrice', label: 'Giá Niêm Yết' },
  { key: 'idecoPrice', label: 'Giá IDECO' },
  { key: 'manufacturer', label: 'Nhà Sản Xuất' },
];

export const ExcelImportModal: React.FC<ExcelImportModalProps> = ({ 
  isOpen, 
  onClose, 
  onImport, 
  onSave, 
  savedData = [], 
  savedMapping 
}) => {
  const [step, setStep] = useState<1 | 2>(1);
  const [data, setData] = useState<ExcelRow[]>([]);
  const [columns, setColumns] = useState<string[]>([]);
  const [mapping, setMapping] = useState<ExcelMapping>({
    name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: ''
  });
  const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());
  const [searchQuery, setSearchQuery] = useState('');
  const [isAutoLoaded, setIsAutoLoaded] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Load saved data correctly on open
  useEffect(() => {
    if (isOpen) {
        if (savedData && savedData.length > 0) {
            setData(savedData);
            const cols = Object.keys(savedData[0]);
            setColumns(cols);
            if (savedMapping) {
                setMapping(savedMapping);
            }
            setStep(2);
            setIsAutoLoaded(true);
        } else {
            reset();
        }
    }
  }, [isOpen]); 

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const jsonData = XLSX.utils.sheet_to_json<ExcelRow>(ws, { header: 1 });

        if (jsonData.length > 0) {
          const headers = jsonData[0] as string[];
          const cleanHeaders = headers.filter(h => h).map(h => String(h).trim());
          setColumns(cleanHeaders);

          // Use the clean headers to parse rows properly
          const rows = XLSX.utils.sheet_to_json<ExcelRow>(ws);
          setData(rows);

          const newMapping: ExcelMapping = { name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: '' };
          cleanHeaders.forEach(col => {
             const lower = col.toLowerCase();
             if (lower.includes('tên thuốc') || lower === 'tên hàng') newMapping.name = col;
             else if (lower.includes('hàm lượng')) newMapping.dosage = col;
             else if (lower.includes('quy cách') || lower.includes('đóng gói')) newMapping.packaging = col;
             else if (lower.includes('công dụng')) newMapping.usage = col;
             else if (lower.includes('niêm yết') || lower.includes('đơn giá hộp vat')) newMapping.listPrice = col;
             else if (lower.includes('giá mua') || lower.includes('giá ideco')) newMapping.idecoPrice = col;
             else if (lower.includes('nhà sản xuất') || lower.includes('đơn vị sx')) newMapping.manufacturer = col;
          });
          setMapping(newMapping);
          setStep(2);
          setIsAutoLoaded(false);
          setSaveStatus('idle');
        }
      } catch (error) {
        alert("Lỗi đọc file Excel. Vui lòng kiểm tra lại định dạng.");
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleMappingChange = (field: keyof ExcelMapping, column: string) => {
    setMapping(prev => ({ ...prev, [field]: column }));
    setSaveStatus('idle');
  };

  const toggleRowSelection = (originalIndex: number) => {
    const newSet = new Set(selectedIndices);
    if (newSet.has(originalIndex)) newSet.delete(originalIndex);
    else newSet.add(originalIndex);
    setSelectedIndices(newSet);
  };

  const filteredData = useMemo(() => {
    if (!searchQuery.trim()) return data.map((row, idx) => ({ row, originalIndex: idx }));
    const lowerQuery = searchQuery.toLowerCase();
    const searchCol = mapping.name || columns[0];
    return data
        .map((row, idx) => ({ row, originalIndex: idx }))
        .filter(({ row }) => {
            const val = row[searchCol];
            return val && String(val).toLowerCase().includes(lowerQuery);
        });
  }, [data, searchQuery, mapping.name, columns]);

  const handleSaveOnly = () => {
    if (data.length === 0) return;
    setSaveStatus('saving');
    onSave(data, mapping); // This updates App state which is tied to localStorage
    setTimeout(() => {
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 3000);
    }, 500);
  };

  const handleApply = () => {
    const selectedRows = data.filter((_, idx) => selectedIndices.has(idx));
    if (selectedRows.length === 0) {
      alert("Vui lòng chọn ít nhất một sản phẩm.");
      return;
    }

    // Strict formatting following mapping
    const formatPriceString = (priceVal: any, packVal: any) => {
        if (priceVal === undefined || priceVal === null) return '';

        let p = '';
        if (typeof priceVal === 'number') {
            p = priceVal.toLocaleString('vi-VN');
        } else {
            // Clean non-numeric characters for proper formatting
            const cleanNum = String(priceVal).replace(/[^0-9]/g, "");
            if (cleanNum) {
                p = parseInt(cleanNum).toLocaleString('vi-VN');
            } else {
                p = String(priceVal);
            }
        }

        if (!p.toLowerCase().includes('đồng')) p += ' đồng';

        if (packVal) {
            const packStr = String(packVal).trim();
            if (packStr) return `${p}/ ${packStr}`;
        }
        return p;
    };

    const newProducts: ProductData[] = selectedRows.map((row, idx) => {
      // DEBUG: console.log('Mapping listPrice to:', mapping.listPrice, 'Value:', row[mapping.listPrice]);
      return {
        id: idx + 1,
        name: row[mapping.name] ? String(row[mapping.name]) : '',
        dosage: row[mapping.dosage] ? String(row[mapping.dosage]) : '',
        usage: row[mapping.usage] ? String(row[mapping.usage]) : '',
        listPrice: formatPriceString(row[mapping.listPrice], row[mapping.packaging]),
        idecoPrice: formatPriceString(row[mapping.idecoPrice], row[mapping.packaging]),
        manufacturer: row[mapping.manufacturer] ? String(row[mapping.manufacturer]) : '',
        isETC: false,
        description: '',
        aspectRatio: 'vertical'
      };
    });

    // Save to library as well to ensure persistence
    onSave(data, mapping);
    onImport(newProducts.slice(0, 3), data, mapping);
    onClose();
  };

  const reset = () => {
      setStep(1);
      setData([]);
      setColumns([]);
      setMapping({ name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: '' });
      setSelectedIndices(new Set());
      setSearchQuery('');
      setIsAutoLoaded(false);
      setSaveStatus('idle');
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden">
        <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
            <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <div className="p-2 bg-green-100 text-green-700 rounded-lg"><Table className="w-5 h-5" /></div>
                {step === 1 ? 'Nhập Dữ Liệu Từ Excel' : 'Soi Chiếu & Chọn Sản Phẩm'}
            </h3>
            <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-2 hover:bg-slate-100 rounded-full"><X className="w-5 h-5" /></button>
        </div>
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
            {step === 1 ? (
                <div className="h-full flex flex-col items-center justify-center py-12 border-2 border-dashed border-slate-300 rounded-xl bg-slate-50 hover:bg-slate-100 transition-colors cursor-pointer"
                     onClick={() => fileInputRef.current?.click()}>
                    <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept=".xlsx, .xls" className="hidden" />
                    <Upload className="w-16 h-16 text-slate-300 mb-4" />
                    <p className="text-lg font-medium text-slate-600">Click để tải file Excel (.xlsx, .xls)</p>
                    <p className="text-xs text-slate-400 mt-2">Hỗ trợ tự động nhận diện cột Tên thuốc, Giá niêm yết, IDECO...</p>
                </div>
            ) : (
                <div className="space-y-6">
                    <div className="bg-slate-50 p-4 rounded-xl border border-slate-200">
                        <div className="flex justify-between items-start mb-3">
                            <h4 className="font-bold text-slate-700 flex items-center gap-2 text-sm uppercase"><ArrowRight className="w-4 h-4 text-indigo-500" /> Bước 1: So chiếu cột dữ liệu</h4>
                            <div className="flex gap-2">
                                <button onClick={handleSaveOnly} className={`flex items-center gap-2 px-4 py-1.5 rounded-lg border text-sm font-bold transition-all ${saveStatus === 'saved' ? 'bg-green-600 text-white border-green-700' : 'bg-white text-indigo-600 border-indigo-200 hover:bg-indigo-50'}`}>
                                    {saveStatus === 'saved' ? <Check className="w-4 h-4" /> : <Save className="w-4 h-4" />} {saveStatus === 'saved' ? 'Đã Lưu Mapping' : 'Lưu Mapping'}
                                </button>
                                {isAutoLoaded && <button onClick={reset} className="px-3 py-1.5 text-xs text-slate-500 hover:text-red-500 font-semibold underline">Nhập file mới</button>}
                            </div>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-x-6 gap-y-3">
                            {MAPPING_FIELDS.map(field => (
                                <div key={field.key} className="flex flex-col">
                                    <label className="text-[11px] font-extrabold text-slate-500 mb-1 uppercase tracking-tight">{field.label}</label>
                                    <select 
                                        className="w-full text-sm border-slate-300 rounded-lg shadow-sm focus:border-indigo-500 focus:ring-indigo-500 bg-white" 
                                        value={mapping[field.key] || ''} 
                                        onChange={(e) => handleMappingChange(field.key, e.target.value)}
                                    >
                                        <option value="">-- Bỏ qua --</option>
                                        {columns.map(col => (<option key={col} value={col}>{col}</option>))}
                                    </select>
                                </div>
                            ))}
                        </div>
                        <p className="text-[10px] text-slate-400 mt-3 italic">* Hệ thống sẽ ưu tiên cột bạn chọn để lấy dữ liệu Tên, Giá và Quy cách.</p>
                    </div>
                    <div className="space-y-3">
                        <div className="flex flex-col md:flex-row justify-between items-end md:items-center gap-3">
                            <h4 className="font-bold text-slate-700 flex items-center gap-2 text-sm uppercase"><Check className="w-4 h-4 text-indigo-500" /> Bước 2: Chọn sản phẩm (Tối đa 3)</h4>
                            <div className="relative w-full md:w-64">
                                <input type="text" placeholder="Tìm tên thuốc..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full pl-9 pr-3 py-1.5 text-sm border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none" />
                                <Search className="w-4 h-4 text-slate-400 absolute left-3 top-2" />
                            </div>
                        </div>
                        <div className="border border-slate-200 rounded-lg overflow-hidden shadow-sm">
                            <div className="overflow-x-auto max-h-[350px]">
                                <table className="w-full text-sm text-left">
                                    <thead className="bg-slate-100 text-slate-600 font-bold border-b border-slate-200 sticky top-0 z-10">
                                        <tr>
                                            <th className="p-3 w-10 text-center">STT</th>
                                            <th className="p-3 w-10 text-center"><Check className="w-4 h-4 mx-auto" /></th>
                                            {columns.map(col => (<th key={col} className="p-3 whitespace-nowrap text-xs uppercase">{col}</th>))}
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100 bg-white">
                                        {filteredData.length > 0 ? filteredData.map(({ row, originalIndex }, idx) => (
                                            <tr key={originalIndex} className={`hover:bg-indigo-50/50 cursor-pointer transition-colors ${selectedIndices.has(originalIndex) ? 'bg-indigo-50' : ''}`} onClick={() => toggleRowSelection(originalIndex)}>
                                                <td className="p-3 text-center text-slate-400 text-xs font-mono">{originalIndex + 1}</td>
                                                <td className="p-3 text-center" onClick={(e) => e.stopPropagation()}>
                                                    <input type="checkbox" checked={selectedIndices.has(originalIndex)} onChange={() => toggleRowSelection(originalIndex)} className="w-4 h-4 rounded text-indigo-600 focus:ring-indigo-500 border-slate-300" />
                                                </td>
                                                {columns.map(col => (<td key={`${originalIndex}-${col}`} className="p-3 whitespace-nowrap max-w-[250px] truncate text-slate-600">{String(row[col] ?? '')}</td>))}
                                            </tr>
                                        )) : (<tr><td colSpan={columns.length + 2} className="p-12 text-center text-slate-400">Không tìm thấy sản phẩm nào phù hợp.</td></tr>)}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
        <div className="px-6 py-4 border-t border-slate-200 bg-slate-50 flex justify-between items-center">
            <div className="text-sm font-bold text-slate-500">
                {selectedIndices.size > 0 && `Đã chọn: ${selectedIndices.size} sản phẩm`}
            </div>
            <div className="flex gap-3">
                <button onClick={onClose} className="px-5 py-2 text-sm font-bold text-slate-600 hover:bg-slate-200 rounded-lg transition-colors">Hủy Bỏ</button>
                {step === 2 && (
                    <button 
                        onClick={handleApply} 
                        disabled={selectedIndices.size === 0} 
                        className="px-8 py-2 text-sm font-extrabold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-lg disabled:opacity-50 flex items-center gap-2 uppercase tracking-wide transition-all"
                    >
                        <Check className="w-5 h-5" /> Nhập Liệu Ngay
                    </button>
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ProductForm } from './components/ProductForm';
import { ResultDisplay } from './components/ResultDisplay';
import { ExternalToolModal } from './components/ExternalToolModal';
import { ExcelImportModal } from './components/ExcelImportModal';
import { ProductData, GeneratedResult, AppState, ExcelMapping } from './types';
import { generateOptimizedPrompt, processProductImageAI } from './services/geminiService';
import { PenTool, BrainCircuit, Table, Image as ImageIcon } from 'lucide-react';
import useLocalStorage from './hooks/useLocalStorage';

const createEmptyProduct = (id: number): ProductData => ({
  id,
  name: '',
  dosage: '',
  usage: '',
  isETC: false,
  listPrice: '',
  idecoPrice: '',
  manufacturer: '',
  description: '',
  imageBase64: undefined,
  mimeType: undefined,
  aspectRatio: 'vertical'
});

const App: React.FC = () => {
  const [products, setProducts] = useState<ProductData[]>([
    createEmptyProduct(1),
    createEmptyProduct(2),
    createEmptyProduct(3)
  ]);

  const [activeTab, setActiveTab] = useState<number>(1);
  const [results, setResults] = useState<GeneratedResult[]>([
    { id: 1, prompt: '', status: 'pending' },
    { id: 2, prompt: '', status: 'pending' },
    { id: 3, prompt: '', status: 'pending' }
  ]);

  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [isImageProcessing, setIsImageProcessing] = useState(false);

  const [masterLibrary, setMasterLibrary] = useLocalStorage<any[]>('excelMasterLibrary', []);
  const [columnMapping, setColumnMapping] = useLocalStorage<ExcelMapping>('excelColumnMapping', {
    name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: ''
  });

  const [externalTool, setExternalTool] = useState<{ isOpen: boolean; type: 'mind' | 'image' | null }>({
    isOpen: false,
    type: null
  });

  const [excelModalOpen, setExcelModalOpen] = useState(false);

  const handleFieldChange = (id: number, field: keyof ProductData, value: string | boolean) => {
    setProducts(prev => prev.map(p => p.id === id ? { ...p, [field]: value } : p));
  };

  const handleImageUpload = (id: number, file: File) => {
    if (file.size > 5 * 1024 * 1024) {
      alert("Ảnh quá lớn. Vui lòng chọn ảnh dưới 5MB.");
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => {
      setProducts(prev => prev.map(p => p.id === id ? { 
        ...p, 
        imageBase64: reader.result as string,
        mimeType: file.type
      } : p));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = (id: number) => {
    setProducts(prev => prev.map(p => p.id === id ? { ...p, imageBase64: undefined, mimeType: undefined } : p));
  };

  const handleProcessImage = async (id: number, task: 'remove-bg' | 'make-3d') => {
    const product = products.find(p => p.id === id);
    if (!product?.imageBase64 || !product.mimeType) return;

    setIsImageProcessing(true);
    try {
      const processedBase64 = await processProductImageAI(product.imageBase64, product.mimeType, task);
      setProducts(prev => prev.map(p => p.id === id ? { 
        ...p, 
        imageBase64: processedBase64,
        mimeType: 'image/png'
      } : p));
    } catch (error) {
      alert("Lỗi xử lý ảnh: " + (error instanceof Error ? error.message : "Vui lòng thử lại."));
    } finally {
      setIsImageProcessing(false);
    }
  };

  const handleGenerateAll = async () => {
    if (!process.env.API_KEY) {
        alert("Thiếu API Key.");
        return;
    }

    setAppState(AppState.PROCESSING);
    setResults(prev => prev.map(r => {
        const prod = products.find(p => p.id === r.id);
        if (prod && prod.name) return { ...r, status: 'loading', prompt: '' };
        return r;
    }));

    const promises = products.map(async (product) => {
      if (!product.name) return;
      try {
        const prompt = await generateOptimizedPrompt(product);
        setResults(prev => prev.map(r => r.id === product.id ? { ...r, prompt, status: 'success' } : r));
      } catch (error) {
        setResults(prev => prev.map(r => r.id === product.id ? { ...r, prompt: String(error), status: 'error' } : r));
      }
    });

    await Promise.all(promises);
    setAppState(AppState.COMPLETE);
  };

  const handleExcelImport = (importedProducts: ProductData[], rawData: any[], mapping: ExcelMapping) => {
    setMasterLibrary(rawData);
    setColumnMapping(mapping);
    setProducts(prev => {
        const newProducts = [...prev];
        importedProducts.forEach((imp, index) => {
            if (index < 3) {
                newProducts[index] = { ...createEmptyProduct(index + 1), ...imp, id: index + 1 };
            }
        });
        return newProducts;
    });
  };

  const handleApplyProductFromLibrary = (productIndex: number, libraryItem: any) => {
    const formatPriceString = (val: any, pack: any) => {
        if (val === undefined || val === null) return '';
        let p = '';
        if (typeof val === 'number') {
            p = val.toLocaleString('vi-VN');
        } else {
            const cleanNum = String(val).replace(/[^0-9]/g, "");
            p = cleanNum ? parseInt(cleanNum).toLocaleString('vi-VN') : String(val);
        }
        if (!p.toLowerCase().includes('đồng')) p += ' đồng';
        return pack ? `${p}/ ${pack}` : p;
    };

    const newProductData: Partial<ProductData> = {
        name: String(libraryItem[columnMapping.name] || ''),
        dosage: String(libraryItem[columnMapping.dosage] || ''),
        usage: String(libraryItem[columnMapping.usage] || ''),
        listPrice: formatPriceString(libraryItem[columnMapping.listPrice], libraryItem[columnMapping.packaging]),
        idecoPrice: formatPriceString(libraryItem[columnMapping.idecoPrice], libraryItem[columnMapping.packaging]),
        manufacturer: String(libraryItem[columnMapping.manufacturer] || ''),
    };

    setProducts(prev => prev.map(p => p.id === productIndex ? { ...p, ...newProductData } : p));
  };

  return (
    <div className="min-h-screen bg-slate-100 p-4 md:p-8">
      <div className="max-w-7xl mx-auto space-y-6">
        <header className="flex flex-col md:flex-row items-center justify-between pb-4 gap-4">
          <div className="flex items-center gap-3">
            <div className="bg-indigo-600 text-white p-2.5 rounded-xl shadow-lg"><PenTool className="w-6 h-6" /></div>
            <div>
              <h1 className="text-2xl md:text-3xl font-extrabold text-slate-800">Pharma Prompt AI</h1>
              <p className="text-slate-500 text-sm font-medium">Xử lý ảnh & tạo Prompt hàng loạt (3 SP)</p>
            </div>
          </div>

          <div className="flex gap-3">
            <button onClick={() => setExcelModalOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-white text-emerald-700 font-bold rounded-lg shadow border border-emerald-200 hover:bg-emerald-50 transition-all active:scale-95"><Table className="w-5 h-5" /> Excel</button>
            <button onClick={() => window.open('https://lmarena.ai/', '_blank')} className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-pink-500 to-rose-500 text-white font-bold rounded-lg shadow-md hover:shadow-lg transition-all active:scale-95"><ImageIcon className="w-5 h-5" /> Tạo Ảnh</button>
            <button onClick={() => setExternalTool({ isOpen: true, type: 'mind' })} className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white font-bold rounded-lg shadow-md hover:shadow-lg transition-all active:scale-95"><BrainCircuit className="w-5 h-5" /> Mind</button>
          </div>
        </header>

        <main className="grid grid-cols-1 lg:grid-cols-12 gap-6">
          <div className="lg:col-span-7">
            <ProductForm 
              products={products} activeTab={activeTab} onTabChange={setActiveTab} onChange={handleFieldChange}
              onImageUpload={handleImageUpload} onRemoveImage={handleRemoveImage} onSubmit={handleGenerateAll}
              onProcessImage={handleProcessImage} isProcessing={appState === AppState.PROCESSING} isImageProcessing={isImageProcessing}
              masterLibrary={masterLibrary} columnMapping={columnMapping} onApplyLibraryProduct={handleApplyProductFromLibrary}
            />
          </div>
          <div className="lg:col-span-5">
            <ResultDisplay results={results} appState={appState} />
          </div>
        </main>
      </div>

      <ExternalToolModal 
        isOpen={externalTool.isOpen} onClose={() => setExternalTool({ isOpen: false, type: null })}
        url={externalTool.type === 'mind' ? 'https://geminigen.ai' : ''} title="GeminiGen AI" icon={<BrainCircuit className="w-5 h-5"/>}
      />

      <ExcelImportModal 
        isOpen={excelModalOpen} onClose={() => setExcelModalOpen(false)}
        onImport={handleExcelImport} onSave={(rawData, mapping) => { setMasterLibrary(rawData); setColumnMapping(mapping); }}
        savedData={masterLibrary} savedMapping={columnMapping}
      />
    </div>
  );
};

export default App;

import { AlertCircle, ArrowRight, Check, FileText, RefreshCw, Save, Search, Table, Upload, X } from 'lucide-react';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import * as XLSX from 'xlsx';
import { ExcelMapping, ProductData } from '../types';

interface ExcelImportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (products: ProductData[], rawData: any[], mapping: ExcelMapping) => void;
  onSave: (rawData: any[], mapping: ExcelMapping) => void;
  savedData?: any[];
  savedMapping?: ExcelMapping;
}

type ExcelRow = Record<string, any>;

const MAPPING_FIELDS: { key: keyof ExcelMapping; label: string }[] = [
  { key: 'name', label: 'Tên Thuốc' },
  { key: 'dosage', label: 'Hàm Lượng' },
  { key: 'packaging', label: 'Quy cách đóng gói' },
  { key: 'usage', label: 'Công Dụng' },
  { key: 'listPrice', label: 'Giá Niêm Yết' },
  { key: 'idecoPrice', label: 'Giá IDECO' },
  { key: 'manufacturer', label: 'Nhà Sản Xuất' },
];

export const ExcelImportModal: React.FC<ExcelImportModalProps> = ({ 
  isOpen, 
  onClose, 
  onImport, 
  onSave, 
  savedData = [], 
  savedMapping 
}) => {
  const [step, setStep] = useState<1 | 2>(1);
  const [data, setData] = useState<ExcelRow[]>([]);
  const [columns, setColumns] = useState<string[]>([]);
  const [mapping, setMapping] = useState<ExcelMapping>({
    name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: ''
  });
  const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());
  const [searchQuery, setSearchQuery] = useState('');
  const [isAutoLoaded, setIsAutoLoaded] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen) {
        if (savedData && savedData.length > 0) {
            setData(savedData);
            const cols = Object.keys(savedData[0]);
            setColumns(cols);
            if (savedMapping) setMapping(savedMapping);
            setStep(2);
            setIsAutoLoaded(true);
        } else {
            reset();
        }
    }
  }, [isOpen]); 

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];

        // 1. Get raw headers to define the structure
        const headerRow = XLSX.utils.sheet_to_json<any[]>(ws, { header: 1 })[0];
        if (!headerRow) return;

        const cleanHeaders = headerRow.map(h => String(h || '').trim());
        setColumns(cleanHeaders);

        // 2. Parse data using cleanHeaders as keys to ensure strict mapping
        // We skip the first row (headers) and use the remaining as data
        const rows = XLSX.utils.sheet_to_json<ExcelRow>(ws, { 
            header: cleanHeaders,
            range: 1, // Start from the second row (index 1)
            defval: '' // Default empty values
        });

        setData(rows);

        const newMapping: ExcelMapping = { name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: '' };
        cleanHeaders.forEach(col => {
             const lower = col.toLowerCase();
             if (lower.includes('tên thuốc') || lower === 'tên hàng' || lower === 'tên biệt dược') newMapping.name = col;
             else if (lower.includes('hàm lượng')) newMapping.dosage = col;
             else if (lower.includes('quy cách') || lower.includes('đóng gói')) newMapping.packaging = col;
             else if (lower.includes('công dụng')) newMapping.usage = col;
             else if (lower.includes('niêm yết') || lower.includes('giá bán vat') || lower.includes('đơn giá hộp vat')) newMapping.listPrice = col;
             else if (lower.includes('giá mua') || lower.includes('giá ideco') || lower.includes('giá đại lý')) newMapping.idecoPrice = col;
             else if (lower.includes('nhà sản xuất') || lower.includes('đơn vị sx')) newMapping.manufacturer = col;
        });

        setMapping(newMapping);
        setStep(2);
        setIsAutoLoaded(false);
        setSaveStatus('idle');
      } catch (error) {
        console.error("Excel Error:", error);
        alert("Lỗi đọc file Excel. Vui lòng kiểm tra lại định dạng file.");
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleMappingChange = (field: keyof ExcelMapping, column: string) => {
    setMapping(prev => ({ ...prev, [field]: column }));
    setSaveStatus('idle');
  };

  const toggleRowSelection = (originalIndex: number) => {
    const newSet = new Set(selectedIndices);
    if (newSet.has(originalIndex)) newSet.delete(originalIndex);
    else {
        if (newSet.size >= 3) {
            alert("Bạn chỉ có thể chọn tối đa 3 sản phẩm.");
            return;
        }
        newSet.add(originalIndex);
    }
    setSelectedIndices(newSet);
  };

  const filteredData = useMemo(() => {
    if (!searchQuery.trim()) return data.map((row, idx) => ({ row, originalIndex: idx }));
    const lowerQuery = searchQuery.toLowerCase();
    const searchCol = mapping.name || columns[0];
    return data
        .map((row, idx) => ({ row, originalIndex: idx }))
        .filter(({ row }) => {
            const val = row[searchCol];
            return val && String(val).toLowerCase().includes(lowerQuery);
        });
  }, [data, searchQuery, mapping.name, columns]);

  const handleSaveOnly = () => {
    if (data.length === 0) return;
    setSaveStatus('saving');
    onSave(data, mapping);
    setTimeout(() => {
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 3000);
    }, 500);
  };

  const handleApply = () => {
    const selectedRows = data.filter((_, idx) => selectedIndices.has(idx));
    if (selectedRows.length === 0) {
      alert("Vui lòng chọn ít nhất một sản phẩm.");
      return;
    }

    // Robust formatting function
    const formatPriceString = (priceVal: any, packVal: any) => {
        if (priceVal === undefined || priceVal === null || priceVal === '') return '';

        let p = '';
        if (typeof priceVal === 'number') {
            p = priceVal.toLocaleString('vi-VN');
        } else {
            // Clean non-numeric characters to try formatting as currency
            const cleanNum = String(priceVal).replace(/[^0-9]/g, "");
            if (cleanNum && !isNaN(parseInt(cleanNum))) {
                p = parseInt(cleanNum).toLocaleString('vi-VN');
            } else {
                p = String(priceVal).trim();
            }
        }

        if (p && !p.toLowerCase().includes('đồng')) {
            p += ' đồng';
        }

        if (packVal && String(packVal).trim()) {
            return `${p}/ ${String(packVal).trim()}`;
        }
        return p;
    };

    const newProducts: ProductData[] = selectedRows.map((row, idx) => {
      // Use the mapping to find the correct data column
      const name = row[mapping.name] ? String(row[mapping.name]).trim() : '';
      const dosage = row[mapping.dosage] ? String(row[mapping.dosage]).trim() : '';
      const usage = row[mapping.usage] ? String(row[mapping.usage]).trim() : '';
      const listPrice = formatPriceString(row[mapping.listPrice], row[mapping.packaging]);
      const idecoPrice = formatPriceString(row[mapping.idecoPrice], row[mapping.packaging]);
      const manufacturer = row[mapping.manufacturer] ? String(row[mapping.manufacturer]).trim() : '';

      return {
        id: idx + 1,
        name,
        dosage,
        usage,
        listPrice,
        idecoPrice,
        manufacturer,
        isETC: false,
        description: '',
        aspectRatio: 'vertical'
      };
    });

    // Persistence: Save current data and mapping state to localStorage
    onSave(data, mapping);
    onImport(newProducts, data, mapping);
    onClose();
  };

  const reset = () => {
      setStep(1);
      setData([]);
      setColumns([]);
      setMapping({ name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: '' });
      setSelectedIndices(new Set());
      setSearchQuery('');
      setIsAutoLoaded(false);
      setSaveStatus('idle');
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden">
        <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
            <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <div className="p-2 bg-emerald-100 text-emerald-700 rounded-lg"><Table className="w-5 h-5" /></div>
                {step === 1 ? 'Nhập Dữ Liệu Từ Excel' : 'Soi Chiếu & Chọn Sản Phẩm'}
            </h3>
            <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-2 hover:bg-slate-100 rounded-full"><X className="w-5 h-5" /></button>
        </div>
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
            {step === 1 ? (
                <div className="h-full flex flex-col items-center justify-center py-12 border-2 border-dashed border-slate-300 rounded-xl bg-slate-50 hover:bg-slate-100 transition-colors cursor-pointer"
                     onClick={() => fileInputRef.current?.click()}>
                    <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept=".xlsx, .xls" className="hidden" />
                    <Upload className="w-16 h-16 text-slate-300 mb-4" />
