import React, { useState } from 'react';
import { ProductForm } from './components/ProductForm';
import { ResultDisplay } from './components/ResultDisplay';
import { ExternalToolModal } from './components/ExternalToolModal';
import { ExcelImportModal } from './components/ExcelImportModal';
import { ProductData, GeneratedResult, AppState, ExcelMapping } from './types';
import { generateOptimizedPrompt, processProductImageAI } from './services/geminiService';
import { PenTool, BrainCircuit, Table, Image as ImageIcon } from 'lucide-react';
import useLocalStorage from './hooks/useLocalStorage';

const createEmptyProduct = (id: number): ProductData => ({
  id,
  name: '',
  dosage: '',
  usage: '',
  isETC: false,
  listPrice: '',
  idecoPrice: '',
  manufacturer: '',
  description: '',
  imageBase64: undefined,
  mimeType: undefined,
  aspectRatio: 'vertical'
});

const App: React.FC = () => {
  const [products, setProducts] = useState<ProductData[]>([
    createEmptyProduct(1),
    createEmptyProduct(2),
    createEmptyProduct(3)
  ]);

  const [activeTab, setActiveTab] = useState<number>(1);
  const [results, setResults] = useState<GeneratedResult[]>([
    { id: 1, prompt: '', status: 'pending' },
    { id: 2, prompt: '', status: 'pending' },
    { id: 3, prompt: '', status: 'pending' }
  ]);

  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [isImageProcessing, setIsImageProcessing] = useState(false);

  const [masterLibrary, setMasterLibrary] = useLocalStorage<any[]>('excelMasterLibrary', []);
  const [columnMapping, setColumnMapping] = useLocalStorage<ExcelMapping>('excelColumnMapping', {
    name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: ''
  });

  const [externalTool, setExternalTool] = useState<{ isOpen: boolean; type: 'mind' | 'image' | null }>({
    isOpen: false,
    type: null
  });

  const [excelModalOpen, setExcelModalOpen] = useState(false);

  const handleFieldChange = (id: number, field: keyof ProductData, value: string | boolean) => {
    setProducts(prev => prev.map(p => p.id === id ? { ...p, [field]: value } : p));
  };

  const handleImageUpload = (id: number, file: File) => {
    if (file.size > 5 * 1024 * 1024) {
      alert("Ảnh quá lớn. Vui lòng chọn ảnh dưới 5MB.");
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => {
      setProducts(prev => prev.map(p => p.id === id ? { 
        ...p, 
        imageBase64: reader.result as string,
        mimeType: file.type
      } : p));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = (id: number) => {
    setProducts(prev => prev.map(p => p.id === id ? { ...p, imageBase64: undefined, mimeType: undefined } : p));
  };

  const handleProcessImage = async (id: number, task: 'remove-bg' | 'make-3d') => {
    const product = products.find(p => p.id === id);
    if (!product?.imageBase64 || !product.mimeType) return;

    setIsImageProcessing(true);
    try {
      const processedBase64 = await processProductImageAI(product.imageBase64, product.mimeType, task);
      setProducts(prev => prev.map(p => p.id === id ? { 
        ...p, 
        imageBase64: processedBase64,
        mimeType: 'image/png'
      } : p));
    } catch (error) {
      alert("Lỗi xử lý ảnh: " + (error instanceof Error ? error.message : "Vui lòng thử lại."));
    } finally {
      setIsImageProcessing(false);
    }
  };

  const handleGenerateAll = async () => {
    if (!process.env.API_KEY) {
        alert("Thiếu API Key.");
        return;
    }

    setAppState(AppState.PROCESSING);
    setResults(prev => prev.map(r => {
        const prod = products.find(p => p.id === r.id);
        if (prod && prod.name) return { ...r, status: 'loading', prompt: '' };
        return r;
    }));

    const promises = products.map(async (product) => {
      if (!product.name) return;
      try {
        const prompt = await generateOptimizedPrompt(product);
        setResults(prev => prev.map(r => r.id === product.id ? { ...r, prompt, status: 'success' } : r));
      } catch (error) {
        setResults(prev => prev.map(r => r.id === product.id ? { ...r, prompt: String(error), status: 'error' } : r));
      }
    });

    await Promise.all(promises);
    setAppState(AppState.COMPLETE);
  };

  const handleExcelImport = (importedProducts: ProductData[], rawData: any[], mapping: ExcelMapping) => {
    setMasterLibrary(rawData);
    setColumnMapping(mapping);
    setProducts(prev => {
        const newProducts = [...prev];
        importedProducts.forEach((imp, index) => {
            if (index < 3) {
                newProducts[index] = { ...createEmptyProduct(index + 1), ...imp, id: index + 1 };
            }
        });
        return newProducts;
    });
  };

  const handleApplyProductFromLibrary = (productIndex: number, libraryItem: any) => {
    const formatPriceString = (val: any, pack: any) => {
        if (val === undefined || val === null || val === '') return '';
        let p = '';
        if (typeof val === 'number') {
            p = val.toLocaleString('vi-VN');
        } else {
            const cleanNum = String(val).replace(/[^0-9]/g, "");
            p = (cleanNum && !isNaN(parseInt(cleanNum))) ? parseInt(cleanNum).toLocaleString('vi-VN') : String(val).trim();
        }
        if (p && !p.toLowerCase().includes('đồng')) p += ' đồng';
        return (pack && String(pack).trim()) ? `${p}/ ${String(pack).trim()}` : p;
    };

    const newProductData: Partial<ProductData> = {
        name: String(libraryItem[columnMapping.name] || '').trim(),
        dosage: String(libraryItem[columnMapping.dosage] || '').trim(),
        usage: String(libraryItem[columnMapping.usage] || '').trim(),
        listPrice: formatPriceString(libraryItem[columnMapping.listPrice], libraryItem[columnMapping.packaging]),
        idecoPrice: formatPriceString(libraryItem[columnMapping.idecoPrice], libraryItem[columnMapping.packaging]),
        manufacturer: String(libraryItem[columnMapping.manufacturer] || '').trim(),
    };

    setProducts(prev => prev.map(p => p.id === productIndex ? { ...p, ...newProductData } : p));
  };

  return (
    <div className="min-h-screen bg-slate-100 p-4 md:p-8">
      <div className="max-w-7xl mx-auto space-y-6">
        <header className="flex flex-col md:flex-row items-center justify-between pb-4 gap-4">
          <div className="flex items-center gap-3">
            <div className="bg-indigo-600 text-white p-2.5 rounded-xl shadow-lg"><PenTool className="w-6 h-6" /></div>
            <div>
              <h1 className="text-2xl md:text-3xl font-extrabold text-slate-800">Pharma Prompt AI</h1>
              <p className="text-slate-500 text-sm font-medium">Xử lý ảnh & tạo Prompt hàng loạt (3 SP)</p>
            </div>
          </div>

          <div className="flex gap-3">
            <button onClick={() => setExcelModalOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-white text-emerald-700 font-bold rounded-lg shadow border border-emerald-200 hover:bg-emerald-50 transition-all active:scale-95"><Table className="w-5 h-5" /> Excel</button>
            <button onClick={() => window.open('https://lmarena.ai/', '_blank')} className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-pink-500 to-rose-500 text-white font-bold rounded-lg shadow-md hover:shadow-lg transition-all active:scale-95"><ImageIcon className="w-5 h-5" /> Tạo Ảnh</button>
            <button onClick={() => setExternalTool({ isOpen: true, type: 'mind' })} className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white font-bold rounded-lg shadow-md hover:shadow-lg transition-all active:scale-95"><BrainCircuit className="w-5 h-5" /> Mind</button>
          </div>
        </header>

        <main className="grid grid-cols-1 lg:grid-cols-12 gap-6">
          <div className="lg:col-span-7">
            <ProductForm 
              products={products} activeTab={activeTab} onTabChange={setActiveTab} onChange={handleFieldChange}
              onImageUpload={handleImageUpload} onRemoveImage={handleRemoveImage} onSubmit={handleGenerateAll}
              onProcessImage={handleProcessImage} isProcessing={appState === AppState.PROCESSING} isImageProcessing={isImageProcessing}
              masterLibrary={masterLibrary} columnMapping={columnMapping} onApplyLibraryProduct={handleApplyProductFromLibrary}
            />
          </div>
          <div className="lg:col-span-5">
            <ResultDisplay results={results} appState={appState} />
          </div>
        </main>
      </div>

      <ExternalToolModal 
        isOpen={externalTool.isOpen} onClose={() => setExternalTool({ isOpen: false, type: null })}
        url={externalTool.type === 'mind' ? 'https://geminigen.ai' : ''} title="GeminiGen AI" icon={<BrainCircuit className="w-5 h-5"/>}
      />

      <ExcelImportModal 
        isOpen={excelModalOpen} onClose={() => setExcelModalOpen(false)}
        onImport={handleExcelImport} onSave={(rawData, mapping) => { setMasterLibrary(rawData); setColumnMapping(mapping); }}
        savedData={masterLibrary} savedMapping={columnMapping}
      />
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { ProductData } from "../types";

/**
 * Generates an optimized image generation prompt based on product data.
 */
export const generateOptimizedPrompt = async (data: ProductData): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const parts: any[] = [];

    if (data.imageBase64 && data.mimeType) {
      const base64Data = data.imageBase64.split(',')[1];
      parts.push({
        inlineData: {
          mimeType: data.mimeType,
          data: base64Data
        }
      });
    }

    const promptInput = `
    Role: Master Creative Director for Pharmaceutical Advertising.
    Task: Create a masterpiece text-to-image prompt for a professional medical poster.

    DATA INPUTS (RENDER EXACTLY AS WRITTEN):
    - Title 1 (Product Name): "${data.name}"
    - Title 2 (List Price): "${data.listPrice}"
    - Title 3 (SPECIAL IDECO PRICE): "${data.idecoPrice}"
    - Title 4 (Manufacturer): "Nhà sản xuất bởi: ${data.manufacturer}"
    - Detail: ${data.dosage} | ${data.usage}
    - Regulatory: ${data.isETC ? 'THUỐC KÊ TOA (REQUIRED)' : 'NONE'}

    CRITICAL VISUAL HIERARCHY:
    1. BRANDING: Analyze the attached image. Render the product box exactly as shown. Use massive 3D typography for "${data.name}" at the top.
    2. UNDISPUTED CENTERPIECE (IDECO PRICE): The text "${data.idecoPrice}" must be the biggest and most attractive element. Render it in a vibrant 3D glowing neon or liquid gold style. Place it inside a premium floating glass badge or high-end promotional ribbon. It MUST stand out as the hero of the poster.
    3. PRICE COMPARISON: Place the list price "${data.listPrice}" nearby but in a significantly smaller, clean, elegant font to show contrast.
    4. MANDATORY BADGE: ${data.isETC ? 'In the top-left corner, place a professional red rectangular stamp with bold white text "Thuốc kê toa".' : ''}
    5. FOOTER: "Nhà sản xuất bởi: ${data.manufacturer}" must be placed cleanly at the bottom edge.

    ARTISTIC SETTING:
    - Environment: Minimalist luxury pharmacy or a high-tech medicine lab.
    - Lighting: Volumetric studio lighting, soft shadows, sharp focus on product.
    - Quality: 8k resolution, photorealistic render, cinematic bokeh background.
    - Format: ${data.aspectRatio === 'vertical' ? '9:16 Portrait' : '16:9 Landscape'}.

    OUTPUT: Only return the English image generation prompt. No introduction or notes.
    `;

    parts.push({ text: promptInput });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview', 
      contents: [{ role: 'user', parts: parts }]
    });

    return response.text || "Failed to generate prompt.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error; 
  }
};

/**
 * Processes a product image using Gemini 2.5 Flash Image.
 */
export const processProductImageAI = async (
  base64Image: string, 
  mimeType: string, 
  task: 'remove-bg' | 'make-3d'
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const data = base64Image.includes(',') ? base64Image.split(',')[1] : base64Image;

  const prompts = {
    'remove-bg': "Remove the background. Keep only the product on pure white. Do not alter labels.",
    'make-3d': "Transform this product photo into a professional 3D packshot on a clean surface."
  };

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data, mimeType } },
          { text: prompts[task] }
        ]
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }
    throw new Error("AI did not return an image.");
  } catch (error) {
    console.error("Image Processing Error:", error);
    throw error;
  }
};

import { AlertCircle, ArrowRight, Check, FileText, RefreshCw, Save, Search, Table, Upload, X } from 'lucide-react';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import * as XLSX from 'xlsx';
import { ExcelMapping, ProductData } from '../types';

interface ExcelImportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (products: ProductData[], rawData: any[], mapping: ExcelMapping) => void;
  onSave: (rawData: any[], mapping: ExcelMapping) => void;
  savedData?: any[];
  savedMapping?: ExcelMapping;
}

type ExcelRow = Record<string, any>;

const MAPPING_FIELDS: { key: keyof ExcelMapping; label: string }[] = [
  { key: 'name', label: 'Tên Thuốc' },
  { key: 'dosage', label: 'Hàm Lượng' },
  { key: 'packaging', label: 'Quy cách đóng gói' },
  { key: 'usage', label: 'Công Dụng' },
  { key: 'listPrice', label: 'Giá Niêm Yết (Tiêu đề 2)' },
  { key: 'idecoPrice', label: 'Giá IDECO (Tiêu đề 3)' },
  { key: 'manufacturer', label: 'Nhà Sản Xuất' },
];

export const ExcelImportModal: React.FC<ExcelImportModalProps> = ({ 
  isOpen, 
  onClose, 
  onImport, 
  onSave, 
  savedData = [], 
  savedMapping 
}) => {
  const [step, setStep] = useState<1 | 2>(1);
  const [data, setData] = useState<ExcelRow[]>([]);
  const [columns, setColumns] = useState<string[]>([]);
  const [mapping, setMapping] = useState<ExcelMapping>({
    name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: ''
  });
  const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());
  const [searchQuery, setSearchQuery] = useState('');
  const [isAutoLoaded, setIsAutoLoaded] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen) {
        if (savedData && savedData.length > 0) {
            setData(savedData);
            const cols = Object.keys(savedData[0]);
            setColumns(cols);
            if (savedMapping) setMapping(savedMapping);
            setStep(2);
            setIsAutoLoaded(true);
        } else {
            reset();
        }
    }
  }, [isOpen]); 

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];

        // 1. Get raw rows to detect headers
        const rawRows = XLSX.utils.sheet_to_json<any[]>(ws, { header: 1 });
        if (rawRows.length === 0) return;

        // Find the first row that actually has data (usually headers)
        const headerIndex = rawRows.findIndex(row => row && row.length > 0);
        if (headerIndex === -1) return;

        const headerRow = rawRows[headerIndex];
        const cleanHeaders = headerRow.map((h: any, idx: number) => {
            const name = String(h || '').trim();
            return name || `Column_${idx + 1}`;
        });

        setColumns(cleanHeaders);

        // 2. Parse data using these EXACT headers as keys
        // We ensure JSON objects use the clean headers to prevent key shifting
        const jsonData = XLSX.utils.sheet_to_json<ExcelRow>(ws, { 
            range: headerIndex,
            defval: '' 
        });

        setData(jsonData);

        const newMapping: ExcelMapping = { name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: '' };
        cleanHeaders.forEach(col => {
             const lower = col.toLowerCase();
             if (lower.includes('tên thuốc') || lower === 'tên hàng' || lower.includes('biệt dược')) newMapping.name = col;
             else if (lower.includes('hàm lượng')) newMapping.dosage = col;
             else if (lower.includes('quy cách') || lower.includes('đóng gói')) newMapping.packaging = col;
             else if (lower.includes('công dụng')) newMapping.usage = col;
             else if (lower.includes('niêm yết') || lower.includes('đơn giá hộp vat') || lower.includes('giá bán')) newMapping.listPrice = col;
             else if (lower.includes('giá mua') || lower.includes('giá ideco') || lower.includes('giá đại lý')) newMapping.idecoPrice = col;
             else if (lower.includes('nhà sản xuất') || lower.includes('đơn vị sx')) newMapping.manufacturer = col;
        });

        setMapping(newMapping);
        setStep(2);
        setIsAutoLoaded(false);
        setSaveStatus('idle');
      } catch (error) {
        console.error("Excel Error:", error);
        alert("Lỗi đọc file Excel. Vui lòng kiểm tra lại định dạng file.");
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleMappingChange = (field: keyof ExcelMapping, column: string) => {
    setMapping(prev => ({ ...prev, [field]: column }));
    setSaveStatus('idle');
  };

  const toggleRowSelection = (originalIndex: number) => {
    const newSet = new Set(selectedIndices);
    if (newSet.has(originalIndex)) newSet.delete(originalIndex);
    else {
        if (newSet.size >= 3) {
            alert("Bạn chỉ có thể chọn tối đa 3 sản phẩm.");
            return;
        }
        newSet.add(originalIndex);
    }
    setSelectedIndices(newSet);
  };

  const filteredData = useMemo(() => {
    if (!searchQuery.trim()) return data.map((row, idx) => ({ row, originalIndex: idx }));
    const lowerQuery = searchQuery.toLowerCase();
    const searchCol = mapping.name || columns[0];
    return data
        .map((row, idx) => ({ row, originalIndex: idx }))
        .filter(({ row }) => {
            const val = row[searchCol];
            return val && String(val).toLowerCase().includes(lowerQuery);
        });
  }, [data, searchQuery, mapping.name, columns]);

  const handleSaveOnly = () => {
    if (data.length === 0) return;
    setSaveStatus('saving');
    onSave(data, mapping);
    setTimeout(() => {
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 3000);
    }, 500);
  };

  const handleApply = () => {
    const selectedRows = data.filter((_, idx) => selectedIndices.has(idx));
    if (selectedRows.length === 0) {
      alert("Vui lòng chọn ít nhất một sản phẩm.");
      return;
    }

    const formatPriceString = (priceVal: any, packVal: any) => {
        if (priceVal === undefined || priceVal === null || priceVal === '') return '';

        let p = '';
        if (typeof priceVal === 'number') {
            p = priceVal.toLocaleString('vi-VN');
        } else {
            // Clean non-numeric except dots for display
            const cleanNum = String(priceVal).replace(/[^0-9]/g, "");
            if (cleanNum && !isNaN(parseInt(cleanNum))) {
                p = parseInt(cleanNum).toLocaleString('vi-VN');
            } else {
                p = String(priceVal).trim();
            }
        }

        if (p && !p.toLowerCase().includes('đồng')) {
            p += ' đồng';
        }

        if (packVal && String(packVal).trim()) {
            return `${p}/ ${String(packVal).trim()}`;
        }
        return p;
    };

    const newProducts: ProductData[] = selectedRows.map((row, idx) => {
      // PRECISE DATA ACCESS: Use the mapping string as a key to the row object
      const name = row[mapping.name] ? String(row[mapping.name]).trim() : '';
      const dosage = row[mapping.dosage] ? String(row[mapping.dosage]).trim() : '';
      const usage = row[mapping.usage] ? String(row[mapping.usage]).trim() : '';
      const listPrice = formatPriceString(row[mapping.listPrice], row[mapping.packaging]);
      const idecoPrice = formatPriceString(row[mapping.idecoPrice], row[mapping.packaging]);
      const manufacturer = row[mapping.manufacturer] ? String(row[mapping.manufacturer]).trim() : '';

      return {
        id: idx + 1,
        name,
        dosage,
        usage,
        listPrice,
        idecoPrice,
        manufacturer,
        isETC: false,
        description: '',
        aspectRatio: 'vertical'
      };
    });

    onSave(data, mapping);
    onImport(newProducts, data, mapping);
    onClose();
  };

  const reset = () => {
      setStep(1);
      setData([]);
      setColumns([]);
      setMapping({ name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: '' });
      setSelectedIndices(new Set());
      setSearchQuery('');
      setIsAutoLoaded(false);
      setSaveStatus('idle');
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-6xl max-h-[95vh] flex flex-col overflow-hidden">
        <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
            <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <div className="p-2 bg-emerald-100 text-emerald-700 rounded-lg"><Table className="w-5 h-5" /></div>
                {step === 1 ? 'Nhập Dữ Liệu Từ Excel' : 'Soi Chiếu & Chọn Sản Phẩm'}
            </h3>
            <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-2 hover:bg-slate-100 rounded-full"><X className="w-5 h-5" /></button>
        </div>
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
            {step === 1 ? (
                <div className="h-full flex flex-col items-center justify-center py-16 border-2 border-dashed border-slate-300 rounded-xl bg-slate-50 hover:bg-slate-100 transition-colors cursor-pointer"
                     onClick={() => fileInputRef.current?.click()}>
                    <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept=".xlsx, .xls" className="hidden" />
                    <Upload className="w-16 h-16 text-slate-300 mb-4" />
                    <p className="text-xl font-bold text-slate-600">Click để tải file Excel (.xlsx, .xls)</p>
                    <p className="text-sm text-slate-400 mt-2">Dữ liệu sẽ được bảo mật và chỉ xử lý trên trình duyệt của bạn</p>
                </div>
            ) : (
                <div className="space-y-6">
                    <div className="bg-slate-50 p-5 rounded-xl border-2 border-emerald-100">
                        <div className="flex justify-between items-start mb-4">
                            <h4 className="font-black text-emerald-800 flex items-center gap-2 text-sm uppercase tracking-wider">
                                <ArrowRight className="w-4 h-4" /> 
                                BƯỚC 1: SO CHIẾU CỘT (Chọn đúng cột 'Giá Hộp' để tránh sai sót)
                            </h4>
                            <button onClick={handleSaveOnly} className={`flex items-center gap-2 px-5 py-2 rounded-lg border-2 text-sm font-black transition-all ${saveStatus === 'saved' ? 'bg-green-600 text-white border-green-700' : 'bg-white text-indigo-700 border-indigo-200 hover:bg-indigo-50'}`}>
                                {saveStatus === 'saved' ? <Check className="w-4 h-4" /> : <Save className="w-4 h-4" />} {saveStatus === 'saved' ? 'ĐÃ LƯU CÀI ĐẶT' : 'LƯU CÀI ĐẶT CỘT'}
                            </button>
